# Content for the remaining US state guides (Oct 2026). Each entry was checked against the state's
# divorce statutes (citations in each guide) using plain-language statute references and, where the app
# already models the state, the formulas in support-engine.js. Federal: TCJA treatment of alimony for
# agreements after Dec 31, 2018; QDRO rules for dividing retirement plans.

TAX = ('A note on taxes', 'For divorce or separation agreements signed after December 31, 2018, alimony is <strong>not deductible</strong> for the person paying and <strong>not taxable income</strong> for the person receiving it, under the federal Tax Cuts and Jobs Act. This changes the real cost and value of every support number, so pre-tax and after-tax figures should never be confused at the negotiating table.')

def house(extra=''):
    return ('p', 'The two biggest assets in most divorces are the family home and retirement savings. A retirement account built up during the marriage is usually divisible even if it is in one spouse\'s name, and dividing a 401(k) or pension takes a separate court order (a QDRO) so the transfer is not taxed as an early withdrawal. Debts are divided too. ' + extra + 'Trading the house for the retirement account is a common move that can quietly cost a great deal if the after-tax values are not compared properly. Modeling these trade-offs before you agree to anything is exactly the kind of decision <span class="brand-italic">Your Divorce Angel</span> is built to help you see clearly.')

def us(slug, name, *, cite, lede, short, prop, separate, alimony, child, timing, glance, faqs, extra_sections=(), alimony_callout=None, house_extra='', questions=None, sys_label=None):
    secs = [('h2', 'How %s divides property' % name)] + [('p', x) for x in prop]
    secs += [('h3', 'Separate property'), ('p', separate)] + list(extra_sections)
    secs += [('h3', 'The house and the retirement accounts'), house(house_extra), ('h2', 'Spousal support')] + [('p', x) for x in alimony]
    if alimony_callout: secs.append(('callout',) + alimony_callout)
    secs += [('callout',) + TAX, ('h2', 'Child support'), ('p', child), ('h2', 'The financial timeline'),
             ('p', 'Two things people consistently underestimate: how long the process takes and how much costs rise once you are running a household alone. ' + timing),
             ('ul', ['<strong>Before filing:</strong> gather a complete picture of assets, debts, income and expenses. Every later decision rests on these.',
                     '<strong>Temporary orders:</strong> temporary support and living arrangements while the case proceeds.',
                     '<strong>Disclosure and negotiation:</strong> both sides exchange financial information; settlement scenarios get modeled and compared.',
                     '<strong>Settlement or trial:</strong> most divorces settle. The ones that go to trial cost more and hand the decisions to a judge.',
                     '<strong>After the judgment:</strong> the division, support and any account transfers are carried out.'])]
    return dict(slug=slug, name=name, template='ohio', verified='facts checked vs ' + cite + '; Oct 2026',
        desc='How money works in a %s divorce: %s' % (name, sys_label or 'property division, separate property, spousal support, child support, timing and the tax treatment of alimony.'),
        about=['%s divorce' % name, 'property division', 'alimony', 'child support'],
        lede=lede, reviewed='Reviewed against %s divorce law (%s).' % (name, cite.split(';')[0]),
        intro='A %s divorce is, at its heart, a financial event. The legal process matters, but most of the decisions that shape your next ten years are about money: who keeps the house, how retirement accounts are split, whether support is paid and for how long. This guide walks through how %s handles each of those questions so you can plan with a clear head instead of guessing.' % (name, name),
        short=short, sections=secs, glance=glance + [('Support tax (post-2018)', 'Not deductible by payer; not taxable to recipient')],
        questions=questions or ['What is the full marital estate, and which assets are actually separate property?',
                                'If we trade the house for the retirement account, are we comparing after-tax values?',
                                'Given our incomes and the length of the marriage, what is the realistic range for support?',
                                'What will my true monthly cost of living be once I am on my own?',
                                'What does each settlement scenario look like five and ten years out, not just on signing day?'],
        faqs=faqs,
        disclaimer='This guide is general financial information about divorce in %s and reflects %s law as of the date noted. It is not legal advice, and laws and individual circumstances change. Always consult a licensed %s attorney for advice specific to your situation.' % (name, name, name))

TAXQ = lambda name: ('Is alimony taxable in %s?' % name, 'For agreements signed after December 31, 2018, alimony is not deductible by the paying spouse and not taxable income to the receiving spouse, under federal law.')

GUIDES = [
us('colorado', 'Colorado', cite='C.R.S. 14-10-113 (property), 14-10-114 (maintenance guideline), 14-10-115 (child support, HB25-1159), 14-10-106 (91-day residency and waiting period)',
   lede='Colorado divides marital property fairly, counts the growth on what you brought in as marital, and gives judges an advisory maintenance formula for most marriages. Here is how Colorado actually handles the money, in plain language.',
   short='Colorado is an <strong>equitable distribution</strong> state: fair, not necessarily equal. Property you owned before or received as a gift is separate, but <strong>its growth during the marriage is marital</strong>. For combined incomes up to <strong>$240,000</strong>, maintenance starts from a <strong>guideline formula and duration table</strong>. Child support uses <strong>income shares</strong>, with a new parenting time table since March 2026.',
   prop=['Under C.R.S. 14-10-113, the court sets aside each spouse\'s separate property and then divides marital property in the proportions it finds just, without regard to marital misconduct. Equitable does not mean 50/50, but an equal split is a common starting point.'],
   separate='Separate property includes gifts, inheritances, property exchanged for what you owned before the marriage, and property excluded by a valid agreement. The key Colorado twist: the <strong>increase in value</strong> of separate property during the marriage <strong>is marital</strong> and can be divided, so the value on the wedding day matters.',
   alimony=['Colorado calls alimony maintenance. When the marriage lasted at least three years and combined income is no more than $240,000 a year, the court starts with an advisory guideline: <strong>40% of the higher earner\'s gross income minus 50% of the lower earner\'s</strong>, capped so the receiving spouse ends up with no more than 40% of the combined income. The guideline is advisory, not presumptive, and the court still weighs the statutory factors.',
            'Guideline duration rises with the length of the marriage, from roughly a third of the marriage at three years to <strong>half the length of the marriage</strong> for longer ones. After 20 years the court can set a longer or indefinite term.'],
   child='Colorado uses an <strong>income shares</strong> model under C.R.S. 14-10-115. Both parents\' gross incomes are added, the basic amount comes from the state schedule, and it is split in proportion to income. Since March 2026 (HB25-1159), every overnight with a parent earns a parenting time credit from a new table.',
   timing='One spouse must have lived in Colorado for 91 days before filing, and the decree cannot be entered until 91 days after service. The court cannot waive that waiting period.',
   glance=[('Property division', 'Equitable distribution (C.R.S. 14-10-113)'), ('Separate property', 'Gifts, inheritances, premarital property; growth during marriage is marital'),
           ('Maintenance', 'Advisory guideline: 40% of higher income minus 50% of lower, 40% cap (14-10-114)'), ('Child support', 'Income shares, new parenting time table (2026)'),
           ('Residency and wait', '91 days residency; 91 days after service')],
   faqs=[('Is Colorado a community property state?', 'No. Colorado is an equitable distribution state: marital property is divided fairly, not necessarily equally, without regard to marital misconduct.'),
         ('Is the growth on my premarital house or account marital in Colorado?', 'Yes. Separate property stays yours, but its increase in value during the marriage is marital property and can be divided.'),
         ('How is maintenance calculated in Colorado?', 'For marriages of at least three years and combined income up to $240,000, the advisory guideline is 40% of the higher earner\'s gross income minus 50% of the lower earner\'s, capped so the recipient has no more than 40% of combined income.'),
         ('How long does maintenance last in Colorado?', 'Under the guideline table it rises from about a third of the marriage length at three years to half the marriage length. After 20 years the court can order a longer or indefinite term.'),
         TAXQ('Colorado')]),

us('minnesota', 'Minnesota', cite='Minn. Stat. 518.58 (property), 518.003 (marital and nonmarital), 518.552 (maintenance, as amended Aug 1, 2024), ch. 518A (child support), 518.10 (residency)',
   lede='Minnesota divides marital property in a just and equitable way, and since August 2024 has clear presumptions on how long spousal maintenance lasts, based on the length of the marriage. Here is how Minnesota handles the money, in plain language.',
   short='Minnesota makes a <strong>just and equitable</strong> division of marital property, with each spouse presumed to have made a substantial contribution. <strong>Nonmarital</strong> property (owned before, gifts, inheritances) stays with its owner. Since 2024, maintenance is presumed <strong>none under 5 years</strong>, <strong>transitional up to half the marriage</strong> for 5 to 20 years, and <strong>indefinite after 20</strong>. Child support uses <strong>income shares</strong>.',
   prop=['Under Minn. Stat. 518.58, the court makes a just and equitable division of marital property without regard to marital misconduct. Property acquired during the marriage is presumed marital whatever the title, and homemaking counts as a substantial contribution.',
         'Values are usually set at the first scheduled prehearing settlement conference, not the separation date, unless you agree otherwise or the court finds another date fairer.'],
   separate='Nonmarital property includes what you owned before the marriage, gifts, inheritances and property excluded by a prenuptial agreement. In rare cases of unfair hardship, a court can award up to half of the other spouse\'s nonmarital property.',
   alimony=['Minnesota calls alimony spousal maintenance. It is available when a spouse lacks enough property for reasonable needs or cannot adequately support themselves. Since August 1, 2024, the law sets presumptions by marriage length: <strong>under 5 years</strong>, presumed no maintenance; <strong>5 to 20 years</strong>, presumed <strong>transitional</strong> maintenance for up to half the length of the marriage; <strong>20 years or more</strong>, presumed <strong>indefinite</strong>.',
            'Courts weigh factors such as each spouse\'s resources, earning capacity, the standard of living (including whether it was funded by debt) and contributions. Retiring at full Social Security age cannot be presumed to be in bad faith.'],
   child='Minnesota uses an <strong>income shares</strong> model (ch. 518A). Each parent\'s income for support is calculated, the combined basic obligation comes from the state table, and it is split by each parent\'s share of the combined income, with a parenting time adjustment.',
   timing='One spouse must have lived in Minnesota for 180 days before filing. Couples who qualify for summary dissolution can have a decree 30 days after filing a joint declaration.',
   glance=[('Property division', 'Just and equitable division of marital property (518.58)'), ('Nonmarital property', 'Premarital, gifts, inheritances; hardship exception'),
           ('Maintenance', 'Presumptions: none under 5 yrs; transitional up to half of 5 to 20 yrs; indefinite 20+ (518.552)'), ('Child support', 'Income shares (ch. 518A)'),
           ('Residency', '180 days')],
   faqs=[('How is property divided in a Minnesota divorce?', 'The court makes a just and equitable division of marital property, without regard to misconduct. Property acquired during the marriage is presumed marital regardless of title.'),
         ('How long does spousal maintenance last in Minnesota?', 'Since August 2024: presumed none for marriages under 5 years, transitional for up to half the marriage length for 5 to 20 years, and indefinite for marriages of 20 years or more. These presumptions can be rebutted.'),
         ('Are gifts and inheritances divided in Minnesota?', 'Generally no. They are nonmarital property, though a court can award part of nonmarital property in cases of unfair hardship.'),
         ('How is child support calculated in Minnesota?', 'With an income shares model: both parents\' incomes set a combined obligation from the state table, split in proportion to income and adjusted for parenting time.'),
         TAXQ('Minnesota')]),

us('maryland', 'Maryland', cite='Md. Code, Fam. Law 8-201 to 8-208 (marital property, monetary award), 11-106 (alimony), 12-202 (child support), 7-103 (grounds after Oct 1, 2023)',
   lede='Maryland divides marital property through a monetary award, prefers short-term rehabilitative alimony, and since October 2023 grants divorce on no-fault grounds only. Here is how Maryland handles the money, in plain language.',
   short='Maryland is an <strong>equitable distribution</strong> state that usually balances things with a <strong>monetary award</strong> rather than moving titles. Property acquired during the marriage is marital however it is titled; premarital, gift and inherited property is not. Alimony is usually <strong>rehabilitative</strong>; <strong>indefinite</strong> alimony needs special findings. Divorce is <strong>no-fault only</strong> since October 1, 2023.',
   prop=['Under Fam. Law 8-205, the court identifies and values marital property and can grant a <strong>monetary award</strong> to adjust the parties\' rights, weighing factors such as contributions, the length of the marriage, age, health and economic circumstances. It can also transfer retirement benefits, jointly owned real estate and family-use personal property. The family home can be left with one spouse for up to three years.',
         'Property acquired after separation but before the final decree is still marital.'],
   separate='Property acquired before the marriage, by gift or inheritance from a third party, excluded by agreement, or directly traceable to those sources is not marital. Mixing funds can make them lose that character, so tracing records matter.',
   alimony=['Maryland recognizes temporary, <strong>rehabilitative</strong> (fixed-term) and <strong>indefinite</strong> alimony, weighing 12 factors including the ability to become self-supporting, the time needed for training, the standard of living and the length of the marriage.',
            'Indefinite alimony requires a finding that the requesting spouse cannot reasonably become self-supporting because of age, illness or disability, or that even after reasonable progress the standards of living would remain <strong>unconscionably disparate</strong>. A request to extend fixed-term alimony must be made during the original term.'],
   child='Maryland uses an <strong>income shares</strong> model (Fam. Law 12-202). Above a combined monthly income of $30,000, support can be set based on the children\'s needs rather than the schedule.',
   timing='If the grounds arose outside Maryland, one spouse must have lived there for six months before filing. Since October 1, 2023 the grounds are a six-month separation (which can be under the same roof if you live separate lives), irreconcilable differences, or mutual consent with a signed settlement.',
   glance=[('Property division', 'Equitable distribution, usually by monetary award (Fam. Law 8-205)'), ('Separate property', 'Premarital, gifts and inheritances, if traceable'),
           ('Alimony', 'Rehabilitative usual; indefinite needs special findings (11-106)'), ('Child support', 'Income shares (12-202)'), ('Grounds', 'No-fault only since Oct 1, 2023')],
   faqs=[('How is property divided in a Maryland divorce?', 'Maryland is an equitable distribution state. The court values the marital property and usually balances the split with a monetary award, and can transfer retirement benefits and jointly owned real estate.'),
         ('Is alimony permanent in Maryland?', 'Usually not. Most alimony is rehabilitative and fixed-term. Indefinite alimony requires findings that the spouse cannot become self-supporting or that the standards of living would remain unconscionably disparate.'),
         ('Do I need to be separated to divorce in Maryland?', 'Not always. Since October 2023 you can divorce on six months\' separation, irreconcilable differences, or mutual consent with a full settlement.'),
         ('How is child support calculated in Maryland?', 'With an income shares model based on both parents\' incomes; above $30,000 a month combined, the court can set support by the children\'s needs.'),
         TAXQ('Maryland')]),

us('wisconsin', 'Wisconsin', cite='Wis. Stat. 767.61 (property, presumed equal), 767.56 (maintenance), 767.511 and DCF 150 (child support), 767.301 (residency), 767.335 (120-day wait)',
   lede='Wisconsin presumes an equal split of marital property, leaves gifts and inheritances with their owner, and sets child support as a percentage of the paying parent\'s income. Here is how Wisconsin handles the money, in plain language.',
   short='Wisconsin presumes an <strong>equal (50/50) division</strong> of marital property, which the court can change after weighing the statutory factors. <strong>Gifts and inheritances</strong> are generally excluded. Maintenance has <strong>no formula</strong>. Child support uses a <strong>percentage of income</strong> standard: 17% for one child up to 34% for five or more.',
   prop=['Wisconsin is a marital property state with a presumption that property is divided equally (Wis. Stat. 767.61). The court can depart from 50/50 after considering factors such as the length of the marriage, contributions, age and health, earning capacity, tax consequences and any marital property agreement.'],
   separate='Property received by gift or inheritance from someone other than your spouse, and property bought with it, is generally excluded, as long as it keeps its identity. The court can divide it anyway if refusing would create hardship for the other spouse or the children.',
   alimony=['Wisconsin maintenance has no formula. The court weighs the length of the marriage, age and health, the property division, education and earning capacity, the ability to become self-supporting, tax effects and any agreement. A common starting point in practice is to equalize incomes after a long marriage, then adjust. Maintenance ends on the recipient\'s remarriage unless agreed otherwise.'],
   child='Wisconsin uses a <strong>percentage of income</strong> standard (DCF 150) applied to the paying parent\'s gross income: <strong>17%</strong> for one child, <strong>25%</strong> for two, <strong>29%</strong> for three, <strong>31%</strong> for four and <strong>34%</strong> for five or more, with adjustments for shared placement and other situations.',
   timing='One spouse must have lived in Wisconsin for six months and in the county for 30 days before filing. No final hearing can happen until 120 days after service or a joint petition.',
   glance=[('Property division', 'Presumed equal division of marital property (767.61)'), ('Excluded', 'Gifts and inheritances, unless hardship'),
           ('Maintenance', 'No formula; statutory factors (767.56)'), ('Child support', '17% / 25% / 29% / 31% / 34% of payer\'s income'), ('Residency and wait', '6 months state, 30 days county; 120 days')],
   faqs=[('Is Wisconsin a community property state?', 'Wisconsin is a marital property state, which works much like community property: marital property is presumed to be divided equally, though the court can change that after weighing the statutory factors.'),
         ('Are inheritances divided in Wisconsin?', 'Generally no. Gifts and inheritances from third parties are excluded if they keep their identity, unless refusing to divide them would cause hardship.'),
         ('How is maintenance decided in Wisconsin?', 'There is no formula. The court weighs factors such as the length of the marriage, earning capacity, the property division and the ability to become self-supporting.'),
         ('How much is child support in Wisconsin?', 'Usually a percentage of the paying parent\'s income: 17% for one child, 25% for two, 29% for three, 31% for four and 34% for five or more, adjusted for shared placement.'),
         TAXQ('Wisconsin')]),

us('tennessee', 'Tennessee', cite='Tenn. Code 36-4-121 (property), 36-5-121 (alimony), 36-5-101 and Rule 1240-02-04 (child support), 36-4-101 (60/90-day wait), 36-4-104 (residency)',
   lede='Tennessee divides marital property equitably, keeps growth on separate property separate, and has four distinct kinds of alimony. Here is how Tennessee handles the money, in plain language.',
   short='Tennessee is an <strong>equitable distribution</strong> state that divides marital property fairly, without regard to fault. <strong>Separate property and its growth</strong> stay with the owner unless mixed in. Alimony comes in four types: <strong>rehabilitative, transitional, in futuro and in solido</strong>. Child support uses <strong>income shares</strong>. Waiting periods are <strong>60 days</strong>, or <strong>90 days</strong> with children.',
   prop=['Under Tenn. Code 36-4-121, marital property, acquired during the marriage up to the final hearing, is divided equitably without regard to marital fault. Retirement benefits earned during the marriage are marital.'],
   separate='Separate property includes what you owned before the marriage, gifts, inheritances, and the income from and growth of separate property. It can become marital through commingling or retitling. Social Security benefits are not marital property.',
   alimony=['Tennessee has four kinds of alimony: <strong>rehabilitative</strong> (short-term, to gain skills; modifiable), <strong>transitional</strong> (to adjust after divorce; generally not modifiable), <strong>alimony in futuro</strong> (long-term, when rehabilitation is not feasible) and <strong>alimony in solido</strong> (a fixed lump sum). Courts weigh 12 factors, and the two most important are the need of the disadvantaged spouse and the other spouse\'s ability to pay.'],
   child='Tennessee uses an <strong>income shares</strong> model. Both parents\' incomes are combined and each pays a proportional share. Generally only the first $10,000 a month of each parent\'s income is counted unless more is shown to be needed.',
   timing='One spouse must have lived in Tennessee for six months before filing. The final decree cannot be entered until 60 days after filing, or 90 days if there are minor children.',
   glance=[('Property division', 'Equitable distribution (36-4-121)'), ('Separate property', 'Premarital, gifts, inheritances and their growth'),
           ('Alimony', 'Rehabilitative, transitional, in futuro, in solido (36-5-121)'), ('Child support', 'Income shares'), ('Waiting period', '60 days, or 90 with children')],
   faqs=[('How is property divided in a Tennessee divorce?', 'Marital property is divided equitably, not necessarily equally, without regard to marital fault. Separate property and its growth generally stay with the owner.'),
         ('What kinds of alimony does Tennessee have?', 'Rehabilitative, transitional, alimony in futuro (long-term) and alimony in solido (a lump sum). Need and ability to pay are the most important factors.'),
         ('How long is the waiting period in Tennessee?', '60 days after filing without minor children, and 90 days with minor children.'),
         ('How is child support calculated in Tennessee?', 'With an income shares model under the state guidelines, generally counting up to $10,000 a month of each parent\'s income.'),
         TAXQ('Tennessee')]),

us('indiana', 'Indiana', cite='Ind. Code 31-15-7-4 and -5 (one-pot property, equal-division presumption), 31-15-7-2 (maintenance), 31-16-6-1 (child support), 31-15-2-6 and -10 (residency, 60-day wait)',
   lede='Indiana puts everything either spouse owns into one pot and presumes an equal split, and it allows spousal maintenance only in a few narrow situations. Here is how Indiana handles the money, in plain language.',
   short='Indiana uses a <strong>one-pot</strong> approach: property owned by either spouse, <strong>including premarital property, gifts and inheritances</strong>, goes into the marital estate, with an <strong>equal split presumed</strong>. Spousal maintenance is <strong>very limited</strong>: incapacity, caring for an incapacitated child, or <strong>rehabilitative support for up to three years</strong>. Child support uses <strong>income shares</strong>.',
   prop=['Under Ind. Code 31-15-7-4, the court can divide all property owned by either or both spouses, whenever and however acquired. An equal division is presumed just and reasonable (31-15-7-5). A spouse who wants more than half must rebut that using factors such as contributions, how and when property was acquired, economic circumstances, dissipation and earning ability. The court must also consider tax consequences.'],
   separate='Indiana does not set separate property aside automatically. Premarital assets, gifts and inheritances are in the pot, but they are one of the reasons a court may depart from 50/50, so records showing where they came from still matter.',
   alimony=['Indiana allows spousal maintenance in only three situations: a spouse who is <strong>physically or mentally incapacitated</strong> and cannot support themselves; a spouse who must stay home to care for an <strong>incapacitated child</strong>; or <strong>rehabilitative maintenance for up to three years</strong> for a spouse whose education or career was interrupted by the marriage. Outside those, financial balancing happens through the property split.'],
   child='Indiana uses an <strong>income shares</strong> model set out in the Indiana Child Support Guidelines. Both parents\' adjusted incomes set a schedule amount, which is shared in proportion to income, with a parenting time credit.',
   timing='One spouse must have lived in Indiana for six months and in the county for three months before filing. No decree can be entered until 60 days after the petition is filed.',
   glance=[('Property division', 'One pot, equal split presumed (31-15-7-4, -5)'), ('Premarital and inherited', 'Included in the pot; may justify an unequal split'),
           ('Maintenance', 'Only for incapacity, a disabled child\'s caregiver, or rehabilitative up to 3 years'), ('Child support', 'Income shares'), ('Residency and wait', '6 months state, 3 months county; 60 days')],
   faqs=[('Is premarital property divided in Indiana?', 'It is included in the marital pot. Indiana presumes an equal split of all property, but premarital property, gifts and inheritances can be reasons for an unequal division.'),
         ('Can I get alimony in Indiana?', 'Only in limited cases: incapacity, caring for an incapacitated child, or rehabilitative maintenance for up to three years after the marriage interrupted your education or career.'),
         ('How long does an Indiana divorce take?', 'At least 60 days after filing, which is the mandatory waiting period; contested cases take longer.'),
         ('How is child support calculated in Indiana?', 'With an income shares model under the Indiana Child Support Guidelines, adjusted for parenting time.'),
         TAXQ('Indiana')]),

us('missouri', 'Missouri', cite='RSMo 452.330 (property), 452.335 (maintenance), 452.340 and Form 14 (child support), 452.305 (90-day residency, 30-day wait)',
   lede='Missouri sets aside each spouse\'s separate property and then divides marital property in the proportions the court finds just. Maintenance depends on need. Here is how Missouri handles the money, in plain language.',
   short='Missouri is an <strong>equitable distribution</strong> state. The court sets aside <strong>separate property</strong> first, then divides marital property and debts justly, which is not always equally, and can consider conduct. <strong>Maintenance</strong> requires need and has no formula. Child support uses the <strong>Form 14</strong> income shares calculation.',
   prop=['Under RSMo 452.330, the court first sets apart each spouse\'s nonmarital property and then divides marital property and debts in the proportions it deems just, considering economic circumstances, contributions (including homemaking), the value of separate property, conduct during the marriage and custody arrangements. Property acquired during the marriage is presumed marital.'],
   separate='Separate property includes gifts, inheritances, property exchanged for separate property, and property excluded by agreement. Its <strong>increase in value stays separate</strong> unless marital assets or effort contributed. Commingling alone does not automatically make it marital, but tracing matters.',
   alimony=['Missouri maintenance requires that the requesting spouse lacks enough property for reasonable needs and cannot support themselves through appropriate employment (RSMo 452.335). The court then weighs factors such as resources, time for training, earning capacity, the standard of living, the length of the marriage, age and health, and conduct. Awards are usually short-term; long-term maintenance is less common. Maintenance can be modifiable or non-modifiable depending on the order.'],
   child='Missouri calculates child support with <strong>Form 14</strong>, an income shares worksheet: both parents\' incomes set a combined amount from the schedule, which is shared in proportion to income, with credits for overnight visits.',
   timing='One spouse must have lived in Missouri for 90 days before filing, and the court cannot enter judgment until 30 days after filing.',
   glance=[('Property division', 'Equitable distribution; separate property set aside first (452.330)'), ('Separate property growth', 'Stays separate unless marital effort or money contributed'),
           ('Maintenance', 'Need-based; no formula (452.335)'), ('Child support', 'Form 14 income shares'), ('Residency and wait', '90 days; 30 days')],
   faqs=[('How is property divided in a Missouri divorce?', 'The court sets aside each spouse\'s separate property and then divides marital property and debts in the proportions it finds just, considering factors including conduct.'),
         ('Does growth on separate property get divided in Missouri?', 'Usually not. Increases in value of separate property stay separate unless marital money or effort contributed to them.'),
         ('How is maintenance decided in Missouri?', 'The requesting spouse must show they lack enough property for reasonable needs and cannot support themselves. The court then weighs statutory factors; there is no formula.'),
         ('How is child support calculated in Missouri?', 'With the Form 14 income shares calculation, based on both parents\' incomes and overnight visits.'),
         TAXQ('Missouri')]),

us('south-carolina', 'South Carolina', cite='S.C. Code 20-3-620 to 20-3-640 (equitable apportionment), 20-3-130 (alimony, adultery bar), 63-17-470 (child support), 20-3-30 (residency), 20-3-10 (grounds)',
   lede='South Carolina apportions marital property equitably, bars alimony for a spouse who committed adultery before separation, and requires a year apart for a no-fault divorce. Here is how South Carolina handles the money, in plain language.',
   short='South Carolina uses <strong>equitable apportionment</strong> of marital property, weighing 15 factors. Premarital property, inheritances and third-party gifts are nonmarital. There are several kinds of alimony, and <strong>adultery before separation bars alimony</strong>. Child support uses <strong>income shares</strong>. No-fault divorce needs <strong>one year of living apart</strong>.',
   prop=['South Carolina courts divide marital property equitably, not necessarily 50/50, weighing 15 factors in S.C. Code 20-3-620, including the length of the marriage, marital misconduct that affected the finances, contributions as a homemaker, earning potential and tax consequences.'],
   separate='Nonmarital property includes inheritances, gifts from third parties and property owned before the marriage. Gifts between spouses are marital. Separate property can become marital by transmutation, for example by mixing it into joint accounts or retitling it jointly.',
   alimony=['South Carolina recognizes <strong>periodic</strong> alimony (ends on death, remarriage or 90 days of cohabitation), <strong>lump-sum</strong>, <strong>rehabilitative</strong> and <strong>reimbursement</strong> alimony. There is no formula; the court weighs 13 factors. A spouse who committed <strong>adultery before the separation or a formal agreement cannot receive alimony</strong>.'],
   child='South Carolina uses an <strong>income shares</strong> model. Both parents\' gross incomes are combined, the guideline table sets the amount, and each pays a proportional share, with a shared parenting adjustment above 109 overnights.',
   timing='If both spouses live in South Carolina, the filing spouse needs three months of residence; if only one does, one year. A no-fault divorce requires one year of living separate and apart before filing, and reconciling restarts the clock. Fault cases cannot be heard for 60 days or finalized for 90 days after filing.',
   glance=[('Property division', 'Equitable apportionment, 15 factors (20-3-620)'), ('Nonmarital', 'Premarital, inheritances, third-party gifts'),
           ('Alimony', 'Periodic, lump-sum, rehabilitative, reimbursement; adultery bar (20-3-130)'), ('Child support', 'Income shares'), ('No-fault ground', 'One year living apart')],
   faqs=[('How is property divided in a South Carolina divorce?', 'Through equitable apportionment: marital property is divided fairly, not necessarily equally, using 15 statutory factors.'),
         ('Does adultery affect alimony in South Carolina?', 'Yes. A spouse who committed adultery before the separation or a formal agreement is barred from receiving alimony.'),
         ('How long do I have to be separated in South Carolina?', 'One year of living separate and apart for a no-fault divorce. Fault grounds such as adultery do not need a separation period.'),
         ('How is child support calculated in South Carolina?', 'With an income shares model based on both parents\' gross incomes, adjusted for shared parenting.'),
         TAXQ('South Carolina')]),

us('alabama', 'Alabama', cite='Ala. Code 30-2-51 (property), 30-2-57 (alimony limits), Ala. R. Jud. Admin. 32 (child support), 30-2-5 (residency), 30-2-8.1 (30-day wait)',
   lede='Alabama divides property equitably and, since 2017, limits how long periodic alimony can last: generally no longer than the marriage, unless it lasted 20 years or more. Here is how Alabama handles the money, in plain language.',
   short='Alabama is an <strong>equitable distribution</strong> state. Premarital property, gifts and inheritances are usually separate unless used for the family. <strong>Periodic alimony</strong> generally cannot last longer than the marriage unless it lasted <strong>20 years or more</strong>, and <strong>rehabilitative alimony</strong> is capped at <strong>five years</strong> except in extraordinary cases. Alimony not requested at divorce cannot be sought later.',
   prop=['Alabama courts divide marital property equitably, which means fairly rather than necessarily equally. Fault, such as adultery, can be considered.'],
   separate='Property owned before the marriage, and gifts and inheritances received during it, are generally separate, unless they were used regularly for the common benefit of the family. Depositing an inheritance into a joint account can make it divisible.',
   alimony=['Alabama recognizes interim, <strong>rehabilitative</strong> and <strong>periodic</strong> alimony, plus alimony in gross. Under Ala. Code 30-2-57, rehabilitative alimony is generally limited to <strong>five years</strong>, and periodic alimony generally <strong>cannot exceed the length of the marriage</strong> unless the marriage lasted <strong>20 years or longer</strong>. Alimony ends on remarriage, cohabitation or death.'],
   alimony_callout=('Ask for it now or lose it', 'If alimony is neither awarded nor reserved in the divorce judgment, it <strong>cannot be awarded later</strong>. Make sure your settlement addresses it.'),
   child='Alabama uses an <strong>income shares</strong> model under Rule 32 of the Alabama Rules of Judicial Administration, combining both parents\' gross incomes and sharing the schedule amount in proportion to income.',
   timing='If only the filing spouse lives in Alabama, they must have lived there for six months. A final judgment cannot be entered until 30 days after filing.',
   glance=[('Property division', 'Equitable distribution'), ('Separate property', 'Premarital, gifts, inheritances unless used for the family'),
           ('Alimony limits', 'Rehabilitative up to 5 years; periodic up to the length of the marriage unless 20+ years (30-2-57)'), ('Child support', 'Income shares (Rule 32)'), ('Waiting period', '30 days')],
   faqs=[('How long does alimony last in Alabama?', 'Rehabilitative alimony is generally capped at five years. Periodic alimony generally cannot last longer than the marriage unless the marriage lasted 20 years or more.'),
         ('Can I ask for alimony after the divorce in Alabama?', 'No. If alimony is neither awarded nor reserved in the divorce judgment, it cannot be awarded later.'),
         ('Are inheritances divided in Alabama?', 'Generally not, unless the inheritance was used regularly for the common benefit of the family or mixed into joint accounts.'),
         ('How is child support calculated in Alabama?', 'With an income shares model under Rule 32, based on both parents\' gross incomes.'),
         TAXQ('Alabama')]),

us('louisiana', 'Louisiana', cite='La. Civil Code arts. 2325 to 2369.8 (community property), 111 to 117 (spousal support), La. R.S. 9:315 (child support), arts. 102, 103 and 103.1 (separation periods), La. R.S. 9:307 (covenant marriage)',
   lede='Louisiana is a civil law, community property state: what you acquire during the marriage is split 50/50, final spousal support is limited and tied to fault, and covenant marriages follow stricter rules. Here is how Louisiana handles the money, in plain language.',
   short='Louisiana is a <strong>community property</strong> state: community assets and debts are divided <strong>equally</strong>. Separate property stays with its owner, with <strong>reimbursement claims</strong> where one estate paid for the other. <strong>Final periodic support</strong> needs need and freedom from fault and is generally capped at <strong>one-third of the payer\'s net income</strong>. No-fault divorce needs <strong>180 days</strong> apart, or <strong>365 days</strong> with children.',
   prop=['Property and debts acquired during the marriage are generally community property and are divided equally when the community ends, by agreement or through a judicial partition.'],
   separate='Property owned before the marriage, and gifts and inheritances to one spouse, are separate. When community money improved separate property, or the reverse, the Civil Code gives a <strong>reimbursement claim</strong>, so records of who paid for what matter.',
   alimony=['Louisiana has two kinds of spousal support. <strong>Interim support</strong> keeps the standard of living during the case and generally ends 180 days after the divorce judgment. <strong>Final periodic support</strong> requires that the claimant be <strong>free from fault</strong> and in need, and is generally <strong>capped at one-third of the payer\'s net income</strong>, with exceptions for domestic abuse. Claims must be made within three years of the divorce.'],
   child='Louisiana uses an <strong>income shares</strong> model (La. R.S. 9:315), combining both parents\' adjusted gross incomes and sharing the schedule amount in proportion to income.',
   timing='For a no-fault divorce, spouses must live separate and apart for 180 days without minor children, or 365 days with minor children. Covenant marriages require longer separation (generally two years for no-fault) and counseling.',
   extra_sections=[('callout', 'Covenant marriage', 'Couples who chose a <strong>covenant marriage</strong> face narrower grounds and longer separation periods, and must attend counseling before filing. Check which kind of marriage you have before you plan the timeline.')],
   glance=[('Property division', 'Community property, equal partition'), ('Separate property', 'Premarital, gifts, inheritances; reimbursement claims'),
           ('Final support', 'Need and freedom from fault; capped at one-third of payer\'s net income'), ('Child support', 'Income shares (R.S. 9:315)'), ('Separation', '180 days, or 365 with children')],
   faqs=[('Is Louisiana a community property state?', 'Yes. Property and debts acquired during the marriage are generally community property and are divided equally.'),
         ('How much spousal support can I get in Louisiana?', 'Final periodic support requires need and freedom from fault, and is generally capped at one-third of the paying spouse\'s net income.'),
         ('How long do I have to be separated in Louisiana?', '180 days without minor children, or 365 days with minor children, for a no-fault divorce. Covenant marriages require longer.'),
         ('How is child support calculated in Louisiana?', 'With an income shares model based on both parents\' adjusted gross incomes.'),
         TAXQ('Louisiana')]),

us('kentucky', 'Kentucky', cite='KRS 403.190 (property), 403.200 (maintenance), 403.212 (child support), 403.140 (180-day residency), 403.170 (60 days apart)',
   lede='Kentucky gives each spouse their nonmarital property back, divides marital property in just proportions, and awards maintenance only when a two-part need test is met. Here is how Kentucky handles the money, in plain language.',
   short='Kentucky is an <strong>equitable distribution</strong> state: each spouse gets their <strong>nonmarital property</strong> back, then marital property is divided in <strong>just proportions</strong> without regard to misconduct. Growth on nonmarital property stays nonmarital unless it came from either spouse\'s efforts. Maintenance needs a <strong>two-part need test</strong>. Divorce is <strong>no-fault only</strong>.',
   prop=['Under KRS 403.190, the court assigns each spouse\'s nonmarital property and then divides marital property in just proportions, considering contributions (including homemaking), the value of property set aside, the length of the marriage and each spouse\'s circumstances. All property acquired during the marriage is presumed marital.'],
   separate='Nonmarital property includes gifts, inheritances and property exchanged for what you owned before the marriage. An <strong>increase in its value</strong> stays nonmarital unless it resulted from the significant efforts of either spouse during the marriage. The spouse claiming nonmarital property must trace it.',
   alimony=['Maintenance requires that the requesting spouse both lacks enough property to meet reasonable needs and cannot support themselves through appropriate employment, or is caring for a child whose condition prevents outside work (KRS 403.200). The court then sets amount and duration using factors such as resources, training time, the standard of living, the length of the marriage, age and health. Fault can limit an award but is not used to punish.'],
   child='Kentucky uses an <strong>income shares</strong> model (KRS 403.212), sharing a schedule amount in proportion to the parents\' combined adjusted gross income.',
   timing='One spouse must have lived in Kentucky for 180 days before filing, and the decree cannot be entered until you have lived apart for 60 days (which can be under the same roof without sexual cohabitation). Kentucky also presumes joint custody and equal parenting time.',
   glance=[('Property division', 'Nonmarital assigned, then just proportions (403.190)'), ('Growth on nonmarital', 'Stays nonmarital unless from either spouse\'s efforts'),
           ('Maintenance', 'Two-part need test (403.200)'), ('Child support', 'Income shares (403.212)'), ('Residency and wait', '180 days; 60 days apart')],
   faqs=[('How is property divided in a Kentucky divorce?', 'Each spouse gets their nonmarital property back, then marital property is divided in just proportions without regard to marital misconduct.'),
         ('Does growth on my premarital assets get divided in Kentucky?', 'Usually not, unless the increase came from the significant efforts of either spouse during the marriage.'),
         ('How do I qualify for maintenance in Kentucky?', 'You must lack enough property for reasonable needs and be unable to support yourself through appropriate work, or be caring for a child whose condition prevents work.'),
         ('How is child support calculated in Kentucky?', 'With an income shares model based on both parents\' combined adjusted gross income.'),
         TAXQ('Kentucky')]),

us('oregon', 'Oregon', cite='ORS 107.105 (property and spousal support), 107.036 (no-fault), ORS 25.275 and OAR 137-050 (child support), 107.075 (residency)',
   lede='Oregon divides property in a way that is just and proper, presumes both spouses contributed equally to what was acquired during the marriage, and has three distinct kinds of spousal support. Here is how Oregon handles the money, in plain language.',
   short='Oregon divides property in a way that is <strong>just and proper</strong>, with a rebuttable <strong>presumption of equal contribution</strong> to property acquired during the marriage. Spousal support comes in three kinds: <strong>transitional, compensatory and maintenance</strong>. Child support uses <strong>income shares</strong>. Divorce is <strong>no-fault only</strong>, with no waiting period.',
   prop=['Under ORS 107.105, the court divides property in a way that is just and proper in all the circumstances. Property acquired during the marriage, whoever holds title, is presumed to have been contributed to equally, and homemaking counts. The costs of sale and taxes must be considered, and retirement plans are divisible.'],
   separate='Property one spouse brought into the marriage, or received by gift or inheritance, is not covered by the equal-contribution presumption, but the court can still include it if justice requires, especially when it was mixed into family assets. Keeping it separate and documented helps.',
   alimony=['Oregon recognizes three kinds of spousal support: <strong>transitional</strong> (to retrain or re-enter work), <strong>compensatory</strong> (to repay a spouse who contributed to the other\'s education or career) and <strong>maintenance</strong> (to keep a similar standard of living, typically after a long marriage). There is no formula; judges weigh the length of the marriage, age and health, income and earning capacity, and parenting responsibilities.'],
   child='Oregon uses an <strong>income shares</strong> model. Combined incomes set a scaled amount, which is shared in proportion to income and adjusted for parenting time, child care, health insurance and a self-support reserve.',
   timing='A spouse must have lived in Oregon for six months before filing. There is no mandatory waiting period, so uncontested cases can finish in weeks; contested cases often take nine months or more. Both spouses must exchange financial documents within 30 days of service.',
   glance=[('Property division', 'Just and proper; presumed equal contribution (ORS 107.105)'), ('Separate property', 'Can be included if justice requires'),
           ('Spousal support', 'Transitional, compensatory, maintenance; no formula'), ('Child support', 'Income shares'), ('Residency', '6 months; no waiting period')],
   faqs=[('How is property divided in an Oregon divorce?', 'In a way that is just and proper. Property acquired during the marriage is presumed to have been contributed to equally by both spouses, whoever holds title.'),
         ('What kinds of spousal support does Oregon have?', 'Transitional, compensatory and maintenance support. There is no formula; the court weighs factors such as the length of the marriage and earning capacity.'),
         ('Is there a waiting period for divorce in Oregon?', 'No. Oregon has no mandatory waiting period, though a spouse must have lived in the state for six months before filing.'),
         ('How is child support calculated in Oregon?', 'With an income shares model, adjusted for parenting time, child care and health insurance.'),
         TAXQ('Oregon')]),

us('oklahoma', 'Oklahoma', cite='43 O.S. 121 (property and alimony), 43 O.S. 134 (termination), 43 O.S. 118 (child support), 43 O.S. 102 (residency), 43 O.S. 107.1 (90-day wait)',
   lede='Oklahoma divides jointly acquired property fairly, lets the court award alimony in money or property, and recognizes common-law marriage. Here is how Oklahoma handles the money, in plain language.',
   short='Oklahoma is an <strong>equitable distribution</strong> state: jointly acquired property is divided fairly, not necessarily equally. Separate property (premarital, gifts, inheritances) usually stays with its owner. <strong>Alimony</strong> is decided case by case and can be paid in <strong>money or property</strong>. Oklahoma recognizes <strong>common-law marriage</strong>, so some couples need a divorce without ever having had a ceremony.',
   prop=['Under 43 O.S. 121, the court divides property acquired jointly during the marriage in a just and reasonable way. Equitable does not mean equal.'],
   separate='Property each spouse owned before the marriage, and gifts and inheritances, generally stay separate. Mixing them with marital funds, or using marital money or effort to improve them, can bring part of their value into the division.',
   alimony=['Oklahoma alimony is based on need and ability to pay, and the court can award it in money or property, in a lump sum or installments. Support alimony ends on either party\'s death or the recipient\'s remarriage, and cohabitation can justify modifying it. A related concept, alimony in lieu of property division, is used to balance the property split and is not modifiable.'],
   child='Oklahoma uses an <strong>income shares</strong> model, sharing a schedule amount in proportion to the parents\' combined gross income, with adjustments for shared parenting.',
   timing='One spouse must have lived in Oklahoma for six months and in the county for 30 days before filing. With minor children there is a 90-day waiting period after filing, and parents must take a co-parenting course. You cannot remarry for six months after the divorce.',
   glance=[('Property division', 'Equitable division of jointly acquired property (43 O.S. 121)'), ('Separate property', 'Premarital, gifts, inheritances'),
           ('Alimony', 'Case by case; money or property'), ('Child support', 'Income shares'), ('Residency and wait', '6 months state, 30 days county; 90 days with children')],
   faqs=[('How is property divided in an Oklahoma divorce?', 'Property acquired jointly during the marriage is divided equitably, which means fairly rather than necessarily equally.'),
         ('How is alimony decided in Oklahoma?', 'Case by case, based on need and ability to pay. It can be paid in money or property, and support alimony ends on death or remarriage.'),
         ('Does Oklahoma recognize common-law marriage?', 'Yes. Couples in a valid common-law marriage need a divorce to end it, and the same property and support rules apply.'),
         ('How is child support calculated in Oklahoma?', 'With an income shares model based on both parents\' gross incomes.'),
         TAXQ('Oklahoma')]),

us('connecticut', 'Connecticut', cite='C.G.S. 46b-81 (property), 46b-82 (alimony), 46b-215a (child support guidelines), 46b-44 (residency), 46b-67 (90-day wait)',
   lede='Connecticut lets the court divide any property either spouse owns, including what you had before the marriage and inheritances, and weighs the cause of the breakdown in alimony. Here is how Connecticut handles the money, in plain language.',
   short='Connecticut is an <strong>all-property</strong> state: the court can assign <strong>any property of either spouse</strong>, including premarital assets, gifts and inheritances. There is <strong>no presumed 50/50 split</strong>. Alimony has <strong>no formula</strong> and the <strong>cause of the breakdown</strong> can be considered. Child support uses <strong>income shares</strong>. There is a <strong>90-day</strong> waiting period.',
   prop=['Under C.G.S. 46b-81, the court can assign to either spouse all or part of the estate of the other, weighing factors such as the length of the marriage, the causes of the breakdown, age, health, occupation, income, employability, needs and each spouse\'s contribution to acquiring and preserving the property. There is no presumption of an equal split.'],
   separate='Connecticut does not exclude separate property automatically. Premarital assets, gifts and inheritances are all available for division, though where an asset came from is one of the things the court weighs. Inheritances you merely expect to receive in the future are not property.',
   alimony=['Alimony under C.G.S. 46b-82 is decided case by case, weighing the length of the marriage, the causes of the dissolution, age, health, income, earning capacity, skills, needs and the property division. Fault can be considered, and there is no formula. Awards can be time-limited or open-ended, and are often reviewed when circumstances change.'],
   child='Connecticut uses an <strong>income shares</strong> model. Both parents\' net incomes are combined, the schedule sets the total obligation and each pays a proportional share. Combined net income above $4,000 a week is decided case by case.',
   timing='A divorce cannot be finalized unless one spouse has lived in Connecticut for 12 months (before filing or before the decree). There is a 90-day waiting period from the return date of the complaint. Couples married 8 years or less with no children and few assets can use a simpler nonadversarial process.',
   glance=[('Property division', 'All property of either spouse can be assigned (46b-81)'), ('Separate property', 'Not automatically excluded'),
           ('Alimony', 'No formula; cause of breakdown considered (46b-82)'), ('Child support', 'Income shares (46b-215a)'), ('Residency and wait', '12 months; 90 days')],
   faqs=[('Are inheritances divided in a Connecticut divorce?', 'They can be. Connecticut is an all-property state, so premarital assets, gifts and inheritances are available for division, though their source is a factor the court weighs.'),
         ('Is property split 50/50 in Connecticut?', 'Not automatically. There is no presumption of equal division; the court weighs the statutory factors, including the causes of the breakdown.'),
         ('How is alimony calculated in Connecticut?', 'There is no formula. The court weighs factors such as the length of the marriage, causes of the dissolution, income, earning capacity and the property division.'),
         ('How is child support calculated in Connecticut?', 'With an income shares model based on both parents\' net incomes.'),
         TAXQ('Connecticut')]),

us('utah', 'Utah', cite='Utah Code 81-4-204 (property, formerly 30-3-5), 81-4-501 to -505 (alimony), Utah Code 81-6 (child support), 81-4-402 (residency and 30-day wait)',
   lede='Utah divides marital property fairly, aims alimony at the standard of living you had during the marriage, and generally limits alimony to the length of the marriage. Here is how Utah handles the money, in plain language.',
   short='Utah is an <strong>equitable distribution</strong> state, and a roughly <strong>equal split</strong> of marital property is the usual starting point. Separate property stays with its owner unless mixed in or grown by marital effort. <strong>Alimony</strong> aims at the marital standard of living and <strong>generally cannot last longer than the marriage</strong>. Parents must complete <strong>divorce orientation and education</strong> courses.',
   prop=['Utah divides marital property equitably. In practice courts start from a roughly equal split and need exceptional circumstances for a significantly unequal one.'],
   separate='Property owned before the marriage, inheritances and gifts to one spouse are generally separate, unless they were commingled or grew in value through marital effort, in which case part of their value can be divided.',
   alimony=['Utah alimony is not automatic and has no formula. The court looks at the recipient\'s needs, earning capacity, and the payer\'s ability to pay, aiming to keep both spouses as close as possible to the standard of living during the marriage. Fault can be considered, but not as punishment. Alimony <strong>generally cannot be ordered for longer than the marriage lasted</strong>, except in limited circumstances.'],
   child='Utah uses an <strong>income shares</strong> model, combining both parents\' gross incomes and sharing the schedule amount in proportion to income.',
   timing='One spouse must have lived in Utah and in the filing county for three months before filing. The decree cannot be entered until 30 days after filing unless the court waives it. Parents with minor children must complete divorce orientation and education courses, and contested cases require mediation.',
   glance=[('Property division', 'Equitable; roughly equal is the usual start'), ('Separate property', 'Premarital, gifts, inheritances unless mixed or grown by marital effort'),
           ('Alimony', 'Standard-of-living focus; generally no longer than the marriage'), ('Child support', 'Income shares'), ('Residency and wait', '3 months; 30 days')],
   faqs=[('How is property divided in a Utah divorce?', 'Equitably. Courts usually start from a roughly equal split of marital property and need exceptional circumstances for a significantly unequal one.'),
         ('How long does alimony last in Utah?', 'Generally no longer than the length of the marriage, except in limited circumstances.'),
         ('How is alimony decided in Utah?', 'By looking at need, earning capacity and ability to pay, with the goal of keeping both spouses close to the marital standard of living. There is no formula.'),
         ('How is child support calculated in Utah?', 'With an income shares model based on both parents\' gross incomes.'),
         TAXQ('Utah')]),

us('iowa', 'Iowa', cite='Iowa Code 598.21 (property), 598.21A (spousal support), Iowa Ct. R. ch. 9 (child support guidelines), 598.5 (residency), 598.19 (90-day wait)',
   lede='Iowa divides all property equitably, including what you owned before the marriage, but generally leaves gifts and inheritances with their owner. Here is how Iowa handles the money, in plain language.',
   short='Iowa is an <strong>equitable distribution</strong> state that can divide property owned by either spouse, <strong>including premarital property</strong>. <strong>Gifts and inheritances</strong> are generally excluded unless mixed in. Spousal support has <strong>traditional, rehabilitative and reimbursement</strong> forms and ignores misconduct. Divorce is <strong>no-fault only</strong>, with a <strong>90-day</strong> wait after service.',
   prop=['Iowa courts divide property equitably under Iowa Code 598.21, which means fairly, not necessarily equally. Premarital property is part of the estate, though bringing it into the marriage is one of the factors the court weighs.'],
   separate='Gifts and inheritances received by one spouse are generally not divided, unless refusing to divide them would be unjust. Mixing them into joint accounts can make them divisible.',
   alimony=['Iowa recognizes <strong>traditional</strong> (long-term), <strong>rehabilitative</strong> and <strong>reimbursement</strong> spousal support. Under Iowa Code 598.21A, the court weighs the length of the marriage, age and health, the property division, earning capacity, the time needed for training, tax consequences and any agreement. Misconduct is not considered; the focus is need and ability to pay.'],
   child='Iowa sets child support under the Iowa Supreme Court\'s guidelines (Iowa Court Rules, chapter 9), based on both parents\' incomes, using the Child Support Guidelines Worksheet.',
   timing='The filing spouse generally must have lived in Iowa for one year, unless the other spouse lives in Iowa and is served there. A decree cannot be entered until 90 days after service.',
   glance=[('Property division', 'Equitable; premarital property included (598.21)'), ('Excluded', 'Gifts and inheritances, unless unjust'),
           ('Spousal support', 'Traditional, rehabilitative, reimbursement; no misconduct (598.21A)'), ('Child support', 'Iowa Supreme Court guidelines, both incomes'), ('Residency and wait', '1 year; 90 days after service')],
   faqs=[('Is premarital property divided in Iowa?', 'It can be. Iowa includes property owned before the marriage in the estate, though bringing it in is a factor in the split. Gifts and inheritances are generally excluded.'),
         ('What types of alimony does Iowa have?', 'Traditional, rehabilitative and reimbursement spousal support. Misconduct is not considered.'),
         ('How long does an Iowa divorce take?', 'At least 90 days after the other spouse is served.'),
         ('How is child support calculated in Iowa?', 'Under the Iowa Supreme Court\'s guidelines, based on both parents\' incomes.'),
         TAXQ('Iowa')]),

us('nevada', 'Nevada', cite='NRS 125.150 (community property division and alimony), NRS 123 (community and separate property), NAC 425 (child support), NRS 125.020 (six-week residency)',
   lede='Nevada is a community property state with an equal split, no formula for alimony, a six-week residency requirement and no waiting period. Here is how Nevada handles the money, in plain language.',
   short='Nevada divides <strong>community property equally</strong> unless the court finds a <strong>compelling reason</strong> in writing. Separate property (premarital, gifts, inheritances) stays with its owner. Alimony has <strong>no formula</strong>. Child support is a <strong>percentage of gross income in tiers</strong>. You can file after <strong>six weeks</strong> of residence and there is no waiting period.',
   prop=['Under NRS 125.150, community property, acquired by either spouse during the marriage, must be divided <strong>equally</strong> unless the court finds a compelling reason, such as wasting or hiding assets, and explains it in writing.'],
   separate='Property owned before the marriage, gifts, inheritances and personal injury awards are separate. Depositing separate money into a joint account used for family expenses can make it community property.',
   alimony=['Nevada alimony has no statutory formula. The court weighs factors listed in NRS 125.150, including the length of the marriage, each spouse\'s income and earning capacity, the standard of living, age and health, and career sacrifices. Long-term alimony is more likely after marriages of 20 years or more. A change of 20% or more in gross monthly income can justify a review.'],
   child='Nevada sets child support as a <strong>percentage of the paying parent\'s gross income</strong>, applied in income tiers, under the Nevada Administrative Code (NAC 425), with adjustments for joint custody.',
   timing='One spouse must have lived in Nevada for six weeks before filing, proved by a resident witness affidavit. There is no waiting period, so uncontested cases can finish in a few weeks.',
   glance=[('Property division', 'Community property, equal split unless compelling reason (NRS 125.150)'), ('Separate property', 'Premarital, gifts, inheritances, injury awards'),
           ('Alimony', 'No formula; statutory factors'), ('Child support', 'Percentage of gross income, in tiers (NAC 425)'), ('Residency and wait', '6 weeks; no waiting period')],
   faqs=[('Is Nevada a community property state?', 'Yes. Community property acquired during the marriage is divided equally unless the court finds a compelling reason and explains it in writing.'),
         ('How is alimony calculated in Nevada?', 'There is no formula. The court weighs statutory factors such as the length of the marriage, earning capacity and the standard of living.'),
         ('How fast can I get divorced in Nevada?', 'After six weeks of residence you can file, and there is no waiting period, so uncontested cases can finish in a few weeks.'),
         ('How is child support calculated in Nevada?', 'As a percentage of the paying parent\'s gross income in tiers, under NAC 425.'),
         TAXQ('Nevada')]),

us('arkansas', 'Arkansas', cite='Ark. Code 9-12-315 (property, equal presumption), 9-12-312 (alimony), Admin. Order No. 10 (child support), 9-12-307 (residency, 30-day wait), 9-12-301 (18-month separation)',
   lede='Arkansas presumes an equal split of marital property, has no irreconcilable differences ground, and requires 18 months apart for a no-fault divorce. Here is how Arkansas handles the money, in plain language.',
   short='Arkansas presumes an <strong>equal (50/50) division</strong> of marital property, and an unequal split needs written reasons. Premarital property, gifts, inheritances and their growth are <strong>nonmarital</strong>. Alimony depends on <strong>need and ability to pay</strong>, not fault. No-fault divorce needs <strong>18 months</strong> of separation.',
   prop=['Under Ark. Code 9-12-315, marital property is divided one-half to each spouse unless the court finds that unfair, considering factors such as the length of the marriage, earning capacity and contributions, and states its reasons in writing.'],
   separate='Nonmarital property includes property owned before the marriage, gifts, inheritances and the increase in value of nonmarital property. Income earned from separate property during the marriage may be marital.',
   alimony=['Arkansas recognizes temporary, <strong>rehabilitative</strong> (the most common) and <strong>permanent</strong> alimony. The primary factors are the requesting spouse\'s need and the other spouse\'s ability to pay; others include the standard of living, the property division, the length of the marriage, health, age and earning capacity. Marital fault is not considered. Alimony ends on remarriage, certain cohabitation or death.'],
   child='Arkansas uses an <strong>income shares</strong> model under Administrative Order No. 10, sharing a schedule amount in proportion to the parents\' incomes.',
   timing='One spouse must have lived in Arkansas for 60 days before filing and three months before the decree, and there is a 30-day waiting period after filing. A no-fault divorce needs 18 continuous months of separation (two years for a covenant marriage).',
   glance=[('Property division', 'Presumed equal; written reasons for unequal (9-12-315)'), ('Nonmarital', 'Premarital, gifts, inheritances and their growth'),
           ('Alimony', 'Need and ability to pay; fault not considered'), ('Child support', 'Income shares (Admin. Order 10)'), ('No-fault ground', '18 months apart')],
   faqs=[('Is property split 50/50 in Arkansas?', 'Marital property is presumed to be divided equally. The court can order an unequal split only if equal would be unfair, and must explain why in writing.'),
         ('Does Arkansas have no-fault divorce?', 'Yes, but it requires 18 continuous months of living apart. There is no irreconcilable differences ground.'),
         ('How is alimony decided in Arkansas?', 'Mainly by need and ability to pay. Marital fault is not considered.'),
         ('How is child support calculated in Arkansas?', 'With an income shares model under Administrative Order No. 10.'),
         TAXQ('Arkansas')]),

us('mississippi', 'Mississippi', cite='Ferguson v. Ferguson (1994) and Armstrong v. Armstrong (1993); Miss. Code 93-5-1, 93-5-2 (grounds), 93-11-65 (child support percentages), 93-5-5 (residency)',
   lede='Mississippi divides marital property with the Ferguson factors, decides alimony with the Armstrong factors, and sets child support as a percentage of the paying parent\'s income. Here is how Mississippi handles the money, in plain language.',
   short='Mississippi is an <strong>equitable distribution</strong> state using the <strong>Ferguson</strong> factors. Separate property (premarital, gifts, inheritances) stays separate unless mixed in. Alimony is decided with the <strong>Armstrong</strong> factors, and fault counts. Child support is a <strong>percentage of adjusted gross income</strong>: 14% for one child up to 26% for five or more. A no-fault divorce needs <strong>both spouses to agree</strong>.',
   prop=['Mississippi courts classify property as marital or separate, value the marital estate, and then divide it equitably using the factors from Ferguson v. Ferguson, including each spouse\'s contributions, the value of separate property, tax consequences and financial security needs.'],
   separate='Separate property generally includes what you owned before the marriage, inheritances and gifts from third parties. It can become marital if commingled, for example by depositing an inheritance into a joint account.',
   alimony=['Mississippi recognizes <strong>periodic</strong>, <strong>lump-sum</strong>, <strong>rehabilitative</strong> (now the most common) and <strong>reimbursement</strong> alimony. Courts weigh twelve factors from Armstrong v. Armstrong, including income, needs, the length of the marriage, the standard of living and fault. Alimony is considered after the property division.'],
   child='Mississippi sets child support as a <strong>percentage of the paying parent\'s adjusted gross income</strong>: <strong>14%</strong> for one child, <strong>20%</strong> for two, <strong>22%</strong> for three, <strong>24%</strong> for four and <strong>26%</strong> for five or more (Miss. Code 93-11-65), with room to deviate.',
   timing='One spouse must have lived in Mississippi for six months before filing. An irreconcilable differences divorce requires both spouses to consent and the complaint to be on file for 60 days; otherwise one of twelve fault grounds must be proved.',
   glance=[('Property division', 'Equitable, Ferguson factors'), ('Separate property', 'Premarital, gifts, inheritances unless commingled'),
           ('Alimony', 'Armstrong factors; fault can count'), ('Child support', '14% / 20% / 22% / 24% / 26% of adjusted income'), ('No-fault', 'Both spouses must agree; 60 days on file')],
   faqs=[('How is property divided in a Mississippi divorce?', 'Equitably, using the Ferguson factors, after separating marital from separate property.'),
         ('Can I get a no-fault divorce in Mississippi if my spouse objects?', 'Generally no. An irreconcilable differences divorce requires both spouses to consent; otherwise a fault ground must be proved.'),
         ('How is alimony decided in Mississippi?', 'With the twelve Armstrong factors, which include fault. Rehabilitative alimony is now the most common type.'),
         ('How much is child support in Mississippi?', 'A percentage of the paying parent\'s adjusted gross income: 14% for one child, 20% for two, 22% for three, 24% for four and 26% for five or more.'),
         TAXQ('Mississippi')]),

us('kansas', 'Kansas', cite='K.S.A. 23-2801 and 23-2802 (property), 23-2902 and 23-2904 (maintenance, 121-month cap), 23-3002 (child support), 23-2703 (residency), 23-2708 (60-day wait)',
   lede='In Kansas all property either spouse owns becomes marital when the case is filed, and maintenance is capped at 121 months unless the court reserved the power to extend it. Here is how Kansas handles the money, in plain language.',
   short='Kansas is an <strong>equitable distribution</strong> state where all property owned by either spouse, <strong>including premarital assets and inheritances</strong>, becomes marital property when the divorce is filed. Maintenance has no formula and is <strong>capped at 121 months</strong>. Child support uses <strong>income shares</strong>. There is a <strong>60-day</strong> wait.',
   prop=['Under K.S.A. 23-2801, property owned by either spouse becomes marital property when the divorce is filed, and the court divides it in a just and reasonable way, considering factors such as the age of the parties, the length of the marriage, how and by whom property was acquired, present and future earning capacity, and dissipation.'],
   separate='Because everything becomes marital on filing, there is no automatic exclusion for premarital property, gifts or inheritances. How and by whom an asset was acquired is a factor, so courts often return such property to the spouse who brought it in.',
   alimony=['Kansas maintenance is set at an amount that is fair, just and equitable, with no formula. It <strong>cannot be ordered for more than 121 months</strong> (just over ten years). An extension beyond that is possible only if the original order allowed the court to review it and there are unusual and compelling circumstances.'],
   child='Kansas uses an <strong>income shares</strong> model under the Kansas Child Support Guidelines, combining both parents\' incomes and sharing the schedule amount in proportion.',
   timing='One spouse must have lived in Kansas for 60 days before filing, and there is a 60-day waiting period after filing that can be waived only in an emergency. You cannot remarry for 30 days after the decree.',
   glance=[('Property division', 'All property becomes marital at filing; just and reasonable split (23-2801)'), ('Premarital and inherited', 'Included; source is a factor'),
           ('Maintenance', 'No formula; capped at 121 months (23-2904)'), ('Child support', 'Income shares'), ('Residency and wait', '60 days; 60 days')],
   faqs=[('Is premarital property divided in Kansas?', 'All property owned by either spouse becomes marital when the divorce is filed, but how and by whom it was acquired is a factor, so it is often returned to the spouse who brought it in.'),
         ('How long can maintenance last in Kansas?', 'No more than 121 months, unless the original order allowed review and there are unusual and compelling circumstances.'),
         ('How long does a Kansas divorce take?', 'At least 60 days after filing, the mandatory waiting period.'),
         ('How is child support calculated in Kansas?', 'With an income shares model under the Kansas Child Support Guidelines.'),
         TAXQ('Kansas')]),

us('new-mexico', 'New Mexico', cite='NMSA 40-3-8 (community, separate and quasi-community property), 40-4-7 (spousal support), 40-4-11.1 (child support guidelines), 40-4-5 (residency)',
   lede='New Mexico is a community property state: what you acquire during the marriage is split equally, and the state offers advisory alimony worksheets. Here is how New Mexico handles the money, in plain language.',
   short='New Mexico divides <strong>community property and debts equally</strong>. Separate property (premarital, gifts, inheritances) stays with its owner, and property bought in another state can be treated as <strong>quasi-community</strong>. Spousal support can be <strong>rehabilitative, transitional, indefinite or lump-sum</strong>, and courts may refer to advisory guidelines. Child support is based on <strong>both parents\' incomes</strong>.',
   prop=['Property and debts acquired during the marriage are presumed community and are divided equally (NMSA 40-3-8). Fault does not affect the community property division.'],
   separate='Separate property includes what you owned before the marriage, gifts and inheritances to one spouse, and property designated separate by written agreement. Property acquired while living in another state that would have been community in New Mexico is treated as <strong>quasi-community</strong> if both spouses live in New Mexico at the divorce.',
   alimony=['New Mexico recognizes <strong>rehabilitative</strong>, <strong>transitional</strong>, <strong>indefinite-duration</strong> and <strong>lump-sum</strong> spousal support (NMSA 40-4-7). Courts weigh need, ability to pay, the length of the marriage and other factors, and may refer to advisory alimony guideline worksheets, which are not binding. For marriages of 20 years or more, the court keeps jurisdiction over support unless the decree says otherwise.'],
   child='New Mexico child support follows statutory guidelines based on both parents\' combined incomes, shared in proportion to income and adjusted for parenting time.',
   timing='One spouse must have lived in New Mexico for six months and be domiciled there. The no-fault ground is incompatibility, and there is no separation requirement before filing.',
   glance=[('Property division', 'Community property, equal split (NMSA 40-3-8)'), ('Quasi-community', 'Out-of-state acquisitions can be treated as community'),
           ('Spousal support', 'Rehabilitative, transitional, indefinite, lump-sum (40-4-7)'), ('Child support', 'Guidelines based on both incomes'), ('Residency', '6 months and domicile')],
   faqs=[('Is New Mexico a community property state?', 'Yes. Property and debts acquired during the marriage are presumed community and divided equally.'),
         ('What is quasi-community property in New Mexico?', 'Property acquired while living in another state that would have been community property in New Mexico. It is treated as community if both spouses live in New Mexico at the divorce.'),
         ('How is spousal support decided in New Mexico?', 'Case by case, based on need, ability to pay and the length of the marriage. Courts may refer to advisory guideline worksheets, which are not binding.'),
         ('How is child support calculated in New Mexico?', 'Under state guidelines based on both parents\' combined incomes and parenting time.'),
         TAXQ('New Mexico')]),

us('nebraska', 'Nebraska', cite='Neb. Rev. Stat. 42-365 and 42-366 (property and alimony), Neb. Ct. R. ch. 4 art. 2 (child support guidelines), 42-349 (residency), 42-363 (60-day wait)',
   lede='Nebraska divides the marital estate equitably, often giving each spouse between a third and a half, and decides alimony case by case. Here is how Nebraska handles the money, in plain language.',
   short='Nebraska is an <strong>equitable distribution</strong> state; awards often give each spouse <strong>one-third to one-half</strong> of the marital estate. Alimony is <strong>discretionary</strong>, weighing contributions and career interruptions, and income disparity alone is not enough. Child support follows the <strong>Nebraska Child Support Guidelines</strong>. Divorce is <strong>no-fault only</strong>, with a <strong>60-day</strong> wait after service.',
   prop=['Under Neb. Rev. Stat. 42-365, the court divides the marital estate equitably. In practice, Nebraska courts generally award each spouse between one-third and one-half of the marital estate, depending on the circumstances. Pensions, retirement plans and accrued vacation or sick pay are included.'],
   separate='Property brought into the marriage, gifts and inheritances are generally set aside to their owner if they can be traced, and are not part of the marital estate.',
   alimony=['Nebraska alimony is discretionary. The court weighs the circumstances of the parties, the length of the marriage, contributions including child care, career interruptions, earning capacity and the overall equities. A difference in income alone is not enough. Alimony ends on either party\'s death or the recipient\'s remarriage unless agreed otherwise.'],
   child='Nebraska sets child support under the Nebraska Child Support Guidelines, which use both parents\' monthly net incomes to set a combined obligation shared in proportion to income.',
   timing='One spouse must have lived in Nebraska for one year before filing, unless you married in Nebraska and one of you has lived there ever since. The decree cannot be entered until 60 days after service, and both parents must complete a parenting course.',
   glance=[('Property division', 'Equitable; often one-third to one-half each (42-365)'), ('Separate property', 'Premarital, gifts, inheritances if traceable'),
           ('Alimony', 'Discretionary; income gap alone not enough'), ('Child support', 'Nebraska Child Support Guidelines'), ('Residency and wait', '1 year; 60 days after service')],
   faqs=[('How is property divided in a Nebraska divorce?', 'Equitably. Courts generally award each spouse between one-third and one-half of the marital estate, depending on the circumstances.'),
         ('How is alimony decided in Nebraska?', 'At the court\'s discretion, weighing contributions, career interruptions, the length of the marriage and earning capacity. A difference in income alone is not enough.'),
         ('How long does a Nebraska divorce take?', 'At least 60 days after the other spouse is served; residency of one year is generally required before filing.'),
         ('How is child support calculated in Nebraska?', 'Under the Nebraska Child Support Guidelines, based on both parents\' net incomes.'),
         TAXQ('Nebraska')]),

us('idaho', 'Idaho', cite='Idaho Code 32-906 and 32-903 (community and separate property), 32-712 (division), 32-705 (maintenance), Idaho R. Fam. L. P. 120 (child support), 32-701 (six-week residency)',
   lede='Idaho is a community property state with a strong presumption of a substantially equal split, a six-week residency requirement and maintenance only when a two-part need test is met. Here is how Idaho handles the money, in plain language.',
   short='Idaho divides <strong>community property substantially equally</strong> unless there are compelling reasons. Separate property (premarital, gifts, inheritances) stays separate, but <strong>income from separate property is generally community</strong>. Maintenance requires a <strong>two-part need test</strong> and fault can count. Residency is just <strong>six weeks</strong>.',
   prop=['Most property and debts acquired during the marriage are community property, whoever holds title (Idaho Code 32-906). Under 32-712, the court divides community property in the proportions it finds just, with a strong presumption of a <strong>substantially equal</strong> division, departing only for compelling reasons such as the length of the marriage, age, health or earning capacity.'],
   separate='Separate property includes what you owned before the marriage, gifts, inheritances and property bought with those funds. In Idaho, <strong>income earned on separate property during the marriage is generally community</strong>, and commingling can convert separate property.',
   alimony=['Idaho maintenance requires that the requesting spouse lacks enough property for reasonable needs and cannot support themselves through employment (Idaho Code 32-705). The court then weighs resources, training time, the length of the marriage, age and health, the paying spouse\'s ability to pay, and fault.'],
   child='Idaho uses an <strong>income shares</strong> model under the Idaho Child Support Guidelines, sharing a schedule amount in proportion to the parents\' incomes.',
   timing='The filing spouse must have lived in Idaho for six full weeks. A decree cannot be entered until about three weeks after service, and parents usually attend a short co-parenting class.',
   glance=[('Property division', 'Community property, substantially equal (32-712)'), ('Separate property', 'Premarital, gifts, inheritances; income on them is community'),
           ('Maintenance', 'Two-part need test; fault can count (32-705)'), ('Child support', 'Income shares'), ('Residency', '6 weeks')],
   faqs=[('Is Idaho a community property state?', 'Yes. Community property is divided substantially equally unless there are compelling reasons for a different split.'),
         ('Is income from my separate property shared in Idaho?', 'Generally yes. Income earned on separate property during the marriage is usually community property.'),
         ('How do I qualify for maintenance in Idaho?', 'You must lack enough property for reasonable needs and be unable to support yourself through employment. Fault can also be considered.'),
         ('How is child support calculated in Idaho?', 'With an income shares model under the Idaho Child Support Guidelines.'),
         TAXQ('Idaho')]),

us('west-virginia', 'West Virginia', cite='W. Va. Code 48-7-101 and 48-7-103 (property), 48-8-101 and 48-6-301 (spousal support), 48-13 (child support), 48-5-105 (residency), 48-5-202 (one-year separation)',
   lede='West Virginia presumes an equal split of marital property and weighs twenty factors, including fault, when deciding spousal support. Here is how West Virginia handles the money, in plain language.',
   short='West Virginia presumes an <strong>equal division</strong> of marital property, which the court can adjust for statutory reasons. Separate property (premarital, gifts, inheritances) stays separate. Spousal support can be <strong>permanent, temporary, rehabilitative or in gross</strong>, using <strong>20 factors</strong> including fault. Child support uses <strong>income shares</strong>.',
   prop=['Under W. Va. Code 48-7-101, marital property is presumed to be divided equally. The court can alter that under 48-7-103 for reasons such as contributions to the marriage and dissipation; fault is not considered except for its economic effect.'],
   separate='Separate property includes what you brought into the marriage, inheritances and gifts to one spouse. Mixing it with marital property, or using marital money or effort to improve it, can make part of its value divisible.',
   alimony=['West Virginia recognizes <strong>permanent</strong>, <strong>temporary</strong>, <strong>rehabilitative</strong> and <strong>in gross</strong> (lump-sum) spousal support (48-8-101). The court weighs 20 factors in 48-6-301, including the length of the marriage, earning ability, needs, the standard of living and marital fault.'],
   child='West Virginia uses an <strong>income shares</strong> model, combining both parents\' adjusted gross incomes and sharing the schedule amount in proportion to income, with a shared parenting adjustment.',
   timing='If you married in West Virginia, one spouse just needs to live there when filing; otherwise one spouse must have lived there for a year. A no-fault divorce can be based on irreconcilable differences or one year of living apart. West Virginia presumes equal custody time is in the child\'s best interest unless shown otherwise.',
   glance=[('Property division', 'Presumed equal division (48-7-101)'), ('Separate property', 'Premarital, gifts, inheritances'),
           ('Spousal support', 'Permanent, temporary, rehabilitative, in gross; 20 factors incl. fault'), ('Child support', 'Income shares'), ('Residency', '1 year, or none if married in WV')],
   faqs=[('How is property divided in a West Virginia divorce?', 'Marital property is presumed to be divided equally, though the court can adjust that for statutory reasons such as contributions and dissipation.'),
         ('Does fault affect alimony in West Virginia?', 'It can. Marital fault is one of 20 factors the court weighs when deciding spousal support.'),
         ('How long do I need to live in West Virginia to divorce?', 'If you married in West Virginia, one spouse only needs to live there when filing. Otherwise one spouse must have lived there for a year.'),
         ('How is child support calculated in West Virginia?', 'With an income shares model based on both parents\' adjusted gross incomes.'),
         TAXQ('West Virginia')]),

us('hawaii', 'Hawaii', cite='HRS 580-47 (property and alimony), 580-51 (modification), Hawaii Child Support Guidelines, HRS 580-1 (residency, Act 69 of 2021), 580-41 (grounds)',
   lede='Hawaii divides property in a way that is just and equitable, decides alimony with thirteen factors and no misconduct, and is strictly no-fault. Here is how Hawaii handles the money, in plain language.',
   short='Hawaii divides property, including joint and separate property, in a way that is <strong>just and equitable</strong>, which is not always 50/50. Alimony can be <strong>time-limited or indefinite</strong>, using <strong>13 factors</strong>; misconduct is not one of them. Child support follows the <strong>Hawaii Child Support Guidelines</strong>. Divorce is <strong>strictly no-fault</strong>.',
   prop=['Under HRS 580-47, the family court divides the parties\' property in a way that is just and equitable, considering each spouse\'s circumstances, the burdens placed on each, and the condition each will be left in. In practice, Hawaii courts start from partnership principles, with each spouse generally keeping the value they brought in and sharing what was built during the marriage.'],
   separate='Property brought into the marriage and gifts or inheritances to one spouse are usually credited back to that spouse, but the court has discretion, and mixing assets can blur the line. Valid premarital agreements are honored.',
   alimony=['Hawaii alimony (spousal support) can be indefinite or for a set period. The court weighs 13 factors, including the length of the marriage, the standard of living, each spouse\'s needs, resources and ability to pay, earning capacity, age, health and child-care responsibilities. Marital misconduct is not considered. Support can be modified or ends on the recipient\'s remarriage.'],
   child='Hawaii sets child support under the <strong>Hawaii Child Support Guidelines</strong>, which use both parents\' incomes and a worksheet that keeps a minimum self-support amount for each parent.',
   timing='Since Act 69 of 2021, you can file for divorce in the circuit where you are domiciled without a minimum period of residence. There is no waiting period. Parents with minor children must attend a parent education program.',
   glance=[('Property division', 'Just and equitable (HRS 580-47)'), ('Separate property', 'Usually credited back; court has discretion'),
           ('Alimony', 'Time-limited or indefinite; 13 factors, no misconduct'), ('Child support', 'Hawaii Child Support Guidelines'), ('Grounds', 'Strictly no-fault')],
   faqs=[('How is property divided in a Hawaii divorce?', 'In a way that is just and equitable, which is not always equal. Courts generally credit back what each spouse brought in and share what was built during the marriage.'),
         ('Does misconduct affect alimony in Hawaii?', 'No. Marital misconduct is not one of the factors the court weighs.'),
         ('How long do I have to live in Hawaii to divorce?', 'Since 2021, you can file in the circuit where you are domiciled without a minimum period of residence.'),
         ('How is child support calculated in Hawaii?', 'Under the Hawaii Child Support Guidelines, based on both parents\' incomes.'),
         TAXQ('Hawaii')]),

us('new-hampshire', 'New Hampshire', cite='RSA 458:16-a (property, equal presumption), 458:19 and 458:19-a (alimony formula and duration), RSA 458-C (child support), 458:5 (residency)',
   lede='New Hampshire presumes an equal split of all property and is one of the few states with an alimony formula: up to 23% of the income difference, for up to half the length of the marriage. Here is how New Hampshire handles the money, in plain language.',
   short='New Hampshire divides <strong>all property of either spouse</strong>, with a <strong>presumed equal split</strong>. <strong>Term alimony</strong> is the lesser of need or <strong>23% of the difference in gross incomes</strong>, for up to <strong>half the length of the marriage</strong>. Child support is a <strong>percentage of combined net income</strong>. There is <strong>no waiting period</strong>.',
   prop=['Under RSA 458:16-a, all property of either or both spouses, however acquired, is divisible, including pensions. The court presumes an equal division unless the statutory factors make that unfair. Pets are property, and the court must consider their care and welfare.'],
   separate='Premarital property, gifts and inheritances are not automatically excluded, but how and when an asset was acquired is one of the factors the court uses to justify an unequal split.',
   alimony=['New Hampshire term alimony is set by formula (RSA 458:19-a): the <strong>lesser of the recipient\'s reasonable need or 23% of the difference</strong> between the parties\' gross incomes. Duration can be <strong>up to 50% of the length of the marriage</strong>. The court can deviate with findings. Alimony must be requested within five years of the decree.'],
   child='New Hampshire calculates child support as a <strong>percentage of the parents\' combined net income</strong> based on the number of children, then divides it between the parents in proportion to income (RSA 458-C).',
   timing='If both spouses live in New Hampshire, you can file right away; if only the filer does and the other cannot be served in the state, the filer needs a year of residence. There is no mandatory waiting period. Parents must complete a Child Impact Program within 45 days of service.',
   glance=[('Property division', 'All property; presumed equal split (458:16-a)'), ('Term alimony', 'Lesser of need or 23% of income difference (458:19-a)'),
           ('Alimony duration', 'Up to half the length of the marriage'), ('Child support', 'Percentage of combined net income (458-C)'), ('Waiting period', 'None')],
   faqs=[('How is alimony calculated in New Hampshire?', 'Term alimony is the lesser of the recipient\'s reasonable need or 23% of the difference in the spouses\' gross incomes, for up to half the length of the marriage.'),
         ('Is property split 50/50 in New Hampshire?', 'An equal division of all property of either spouse is presumed, unless the statutory factors make that unfair.'),
         ('Are inheritances divided in New Hampshire?', 'They can be, because all property is divisible, but how an asset was acquired is a reason the court may give it back to one spouse.'),
         ('How is child support calculated in New Hampshire?', 'As a percentage of the parents\' combined net income, divided in proportion to income.'),
         TAXQ('New Hampshire')]),

us('maine', 'Maine', cite='19-A M.R.S. 953 (property), 951-A (spousal support types and presumptions), 19-A M.R.S. ch. 63 (child support), 901 (residency)',
   lede='Maine sets aside nonmarital property, divides marital property justly, and limits general spousal support for marriages under 20 years. Here is how Maine handles the money, in plain language.',
   short='Maine is an <strong>equitable distribution</strong> state: nonmarital property is set aside, then marital property is divided justly. Maine has five kinds of spousal support, and <strong>general support</strong> is presumed unavailable for marriages under <strong>10 years</strong> and limited to <strong>half the marriage</strong> for 10 to 20 years. There is a <strong>60-day</strong> waiting period.',
   prop=['Under 19-A M.R.S. 953, the court first sets apart each spouse\'s nonmarital property and then divides marital property in the proportions it considers just. Property acquired during the marriage is presumed marital, whoever holds title. The court also considers a pet\'s welfare.'],
   separate='Nonmarital property includes what you owned before the marriage, gifts and inheritances, property acquired after a legal separation, property excluded by agreement, and the increase in value of nonmarital property (unless marital effort or money caused it).',
   alimony=['Maine recognizes five kinds of spousal support: <strong>general</strong>, <strong>transitional</strong>, <strong>reimbursement</strong>, <strong>nominal</strong> (to keep the right to ask later) and <strong>interim</strong>. For general support there are rebuttable presumptions: for marriages <strong>under 10 years</strong>, it should not be awarded; for marriages of <strong>10 to 20 years</strong>, it should not last longer than <strong>half the length of the marriage</strong>.'],
   child='Maine uses an <strong>income shares</strong> model under its child support guidelines, combining both parents\' gross incomes and sharing the table amount in proportion to income.',
   timing='One spouse must have lived in Maine for six months before filing, unless another residency condition applies. There is a 60-day waiting period after filing, and mediation is required in contested custody cases.',
   glance=[('Property division', 'Nonmarital set aside; marital divided justly (953)'), ('Nonmarital', 'Premarital, gifts, inheritances and their passive growth'),
           ('Spousal support', 'General, transitional, reimbursement, nominal, interim (951-A)'), ('General support limits', 'Presumed none under 10 yrs; up to half the marriage for 10 to 20 yrs'), ('Waiting period', '60 days')],
   faqs=[('How is property divided in a Maine divorce?', 'Each spouse\'s nonmarital property is set aside, then marital property is divided in the proportions the court considers just.'),
         ('How long does spousal support last in Maine?', 'For general support, there is a presumption against it for marriages under 10 years, and a presumption that it lasts no more than half the marriage for marriages of 10 to 20 years.'),
         ('What is nominal spousal support in Maine?', 'A token award that preserves the right to ask for more support later if circumstances change.'),
         ('How is child support calculated in Maine?', 'With an income shares model based on both parents\' gross incomes.'),
         TAXQ('Maine')]),

us('montana', 'Montana', cite='MCA 40-4-202 (equitable apportionment), 40-4-203 (maintenance), 40-4-204 and ARM 37.62 (child support guidelines), 40-4-104 (residency)',
   lede='Montana apportions all property of either spouse equitably, whenever acquired, and awards maintenance only when a two-part need test is met. Here is how Montana handles the money, in plain language.',
   short='Montana uses <strong>equitable apportionment</strong> of <strong>all property of either spouse</strong>, whenever acquired, without regard to misconduct. Premarital, gift and inherited property can be considered, with weight given to who contributed. Maintenance requires a <strong>two-part need test</strong>. Child support follows the <strong>Montana Child Support Guidelines</strong>, which use a Melson-style formula.',
   prop=['Under MCA 40-4-202, the court equitably apportions all property and assets of either or both spouses, however and whenever acquired and whoever holds title. Marital misconduct cannot be considered.'],
   separate='Property owned before the marriage, gifts and inheritances are in the estate, but the court considers the contributions of the other spouse to them. If the other spouse contributed little, the court usually gives that property back to its owner.',
   alimony=['Montana maintenance requires that the requesting spouse lacks enough property to meet reasonable needs and cannot support themselves through appropriate employment, or is caring for a child whose condition makes working inappropriate (MCA 40-4-203). There is no formula; judges decide amount and duration.'],
   child='Montana uses the <strong>Montana Child Support Guidelines</strong>, a Melson-style formula that first sets aside a basic amount for each parent\'s own needs, then shares the children\'s needs and a portion of remaining income. The guideline amount is presumed correct.',
   timing='One spouse must have lived or been stationed in Montana for 90 days before filing. Both spouses must exchange sworn financial disclosures within 60 days of service.',
   glance=[('Property division', 'Equitable apportionment of all property (MCA 40-4-202)'), ('Premarital and inherited', 'Included; other spouse\'s contribution weighed'),
           ('Maintenance', 'Two-part need test (40-4-203)'), ('Child support', 'Montana Child Support Guidelines (Melson-style)'), ('Residency', '90 days')],
   faqs=[('Is inherited property divided in Montana?', 'It is part of the estate, but the court weighs the other spouse\'s contributions to it. Where they contributed little, it usually stays with the owner.'),
         ('How do I qualify for maintenance in Montana?', 'You must lack enough property for reasonable needs and be unable to support yourself through appropriate work, or be caring for a child whose condition prevents work.'),
         ('Does misconduct affect property division in Montana?', 'No. Marital misconduct cannot be considered when dividing property.'),
         ('How is child support calculated in Montana?', 'Under the Montana Child Support Guidelines, a Melson-style formula that protects each parent\'s own basic needs first.'),
         TAXQ('Montana')]),

us('rhode-island', 'Rhode Island', cite='R.I. Gen. Laws 15-5-16.1 (property), 15-5-16 (alimony), Family Court child support guidelines, 15-5-12 (residency), 15-5-3.1 (irreconcilable differences)',
   lede='Rhode Island divides marital property equitably using twelve factors, treats alimony as mainly rehabilitative, and requires a year of residence before filing. Here is how Rhode Island handles the money, in plain language.',
   short='Rhode Island is an <strong>equitable distribution</strong> state using <strong>12 factors</strong>, including conduct. Gifts and inheritances are generally separate unless commingled. <strong>Alimony</strong> is mainly <strong>rehabilitative</strong>, with indefinite support possible when self-sufficiency is not realistic. Child support follows the <strong>Family Court guidelines</strong>. You need <strong>one year</strong> of residence.',
   prop=['Under R.I. Gen. Laws 15-5-16.1, the Family Court divides marital property equitably using twelve factors, including the length of the marriage, conduct during the marriage, contributions and dissipation of assets. Property acquired during the marriage is generally marital.'],
   separate='Property held before the marriage and gifts or inheritances are generally separate, but commingling can convert them, and an increase in value caused by either spouse\'s efforts during the marriage can be divided.',
   alimony=['Rhode Island alimony has no formula and is primarily <strong>rehabilitative</strong>, meant to help a spouse become self-sufficient, but it can be indefinite where self-sufficiency is not reasonably achievable (R.I. Gen. Laws 15-5-16). Factors include the length of the marriage, conduct, health, age, income and employability. Property is divided first, and alimony ends on the recipient\'s remarriage.'],
   child='Rhode Island sets child support under the Family Court\'s child support guidelines, using both parents\' incomes and a guideline worksheet.',
   timing='One spouse must have lived in Rhode Island for one year before filing. For an irreconcilable differences divorce, the final judgment usually enters about three months after the nominal hearing, so roughly five to six months from filing for an uncontested case.',
   glance=[('Property division', 'Equitable, 12 factors (15-5-16.1)'), ('Separate property', 'Premarital, gifts, inheritances unless commingled'),
           ('Alimony', 'Mainly rehabilitative; indefinite possible (15-5-16)'), ('Child support', 'Family Court guidelines'), ('Residency', '1 year')],
   faqs=[('How is property divided in a Rhode Island divorce?', 'Equitably, using twelve statutory factors including conduct, contributions and dissipation of assets.'),
         ('Is alimony permanent in Rhode Island?', 'Usually not. It is mainly rehabilitative, though it can be indefinite where becoming self-sufficient is not reasonably achievable.'),
         ('How long does a Rhode Island divorce take?', 'For an uncontested irreconcilable differences divorce, typically five to six months from filing, because final judgment enters about three months after the nominal hearing.'),
         ('How is child support calculated in Rhode Island?', 'Under the Family Court\'s child support guidelines, based on both parents\' incomes.'),
         TAXQ('Rhode Island')]),

us('delaware', 'Delaware', cite='13 Del. C. 1513 (property), 1512 (alimony, 50% duration rule), Family Court Melson formula (child support), 1504 (residency), 1505 and 1507 (six months apart)',
   lede='Delaware divides marital property without regard to misconduct, limits alimony to half the length of marriages under 20 years, and uses the Melson formula for child support. Here is how Delaware handles the money, in plain language.',
   short='Delaware is an <strong>equitable distribution</strong> state that ignores marital misconduct. <strong>Alimony</strong> needs proof of dependency and is generally limited to <strong>50% of the length of the marriage</strong>, unless the marriage lasted <strong>20 years or more</strong>. Child support uses the <strong>Melson formula</strong>. Spouses must be <strong>separated for six months</strong> before the divorce is granted.',
   prop=['Under 13 Del. C. 1513, the Family Court divides marital property equitably, without regard to marital misconduct, considering factors such as homemaker contributions, the length of the marriage and custodial arrangements. Property acquired during the marriage is presumed marital, whatever the title.'],
   separate='Gifts from third parties, property owned before the marriage and its appreciation, property exchanged for it, and property excluded by a valid agreement are not marital property.',
   alimony=['A Delaware spouse must show <strong>dependency</strong> to receive alimony. For marriages of under 20 years, alimony generally <strong>cannot last longer than half the length of the marriage</strong>; after 20 years there is no time limit (13 Del. C. 1512). Alimony ends on death, the recipient\'s remarriage, or cohabitation with an intimate partner.'],
   child='Delaware uses the <strong>Melson formula</strong>, which first reserves a basic self-support amount for each parent, then shares the children\'s primary needs and a standard-of-living adjustment in proportion to income.',
   timing='One spouse must have lived in Delaware for six months before filing, and the spouses must have lived separate and apart for six months before the divorce is granted (separate bedrooms and no sexual relations can count, even under one roof). Parents must complete a parent education course.',
   glance=[('Property division', 'Equitable, no misconduct (13 Del. C. 1513)'), ('Separate property', 'Premarital and its growth, third-party gifts'),
           ('Alimony', 'Dependency required; up to half the marriage if under 20 years (1512)'), ('Child support', 'Melson formula'), ('Separation', '6 months before the decree')],
   faqs=[('How long does alimony last in Delaware?', 'For marriages under 20 years, generally no longer than half the length of the marriage. After 20 years there is no time limit.'),
         ('Does misconduct affect property division in Delaware?', 'No. Marital property is divided without regard to marital misconduct.'),
         ('How is child support calculated in Delaware?', 'With the Melson formula, which protects each parent\'s basic needs before sharing the children\'s needs in proportion to income.'),
         ('Do I need to be separated to divorce in Delaware?', 'Yes. Spouses must have lived separate and apart for six months before the divorce is granted, though you can file sooner.'),
         TAXQ('Delaware')]),

us('south-dakota', 'South Dakota', cite='SDCL 25-4-44 (all-property division), 25-4-41 (alimony), SDCL 25-7-6.1 et seq. (child support), 25-4-30 (residency), 60-day wait',
   lede='South Dakota can divide all property either spouse owns, including premarital and inherited assets, and decides alimony case by case. Here is how South Dakota handles the money, in plain language.',
   short='South Dakota is an <strong>all-property</strong> state: the court can divide property of either spouse, <strong>including premarital assets and inheritances</strong>, in an equitable way. Alimony is usually <strong>rehabilitative</strong>, and fault can be a factor. Child support uses <strong>income shares</strong>. There is a <strong>60-day</strong> wait after service.',
   prop=['Under SDCL 25-4-44, the court equitably divides the property of the parties, whether title is held by one or both. Where an asset came from (earned, inherited, gifted) can influence the outcome but does not control it. Dissipation and hidden assets can be considered.'],
   separate='There is no automatic exemption for premarital, gifted or inherited property. In practice courts often leave such property with its owner when the other spouse contributed little to it, but they are not required to.',
   alimony=['South Dakota recognizes temporary, <strong>rehabilitative</strong> (the most common) and <strong>permanent</strong> alimony. Factors come from case law: the length of the marriage, earning capacity, finances after the property division, age and health, the standard of living and fault. Ending alimony on remarriage or death requires a motion.'],
   child='South Dakota uses an <strong>income shares</strong> model, combining both parents\' net incomes and sharing the schedule amount in proportion to income.',
   timing='The filing spouse must be a South Dakota resident when the case begins (there is no minimum period). A final decree cannot be entered until 60 days after service. A no-fault divorce on irreconcilable differences needs both spouses to agree or the other spouse not to respond.',
   glance=[('Property division', 'All property, equitable (SDCL 25-4-44)'), ('Premarital and inherited', 'Not automatically exempt'),
           ('Alimony', 'Rehabilitative most common; fault can count'), ('Child support', 'Income shares'), ('Residency and wait', 'Resident at filing; 60 days after service')],
   faqs=[('Are inheritances divided in South Dakota?', 'They can be. South Dakota is an all-property state, though courts often leave inherited property with the owner when the other spouse contributed little.'),
         ('How is alimony decided in South Dakota?', 'Case by case, weighing factors such as the length of the marriage, earning capacity, age, health and fault. Rehabilitative alimony is most common.'),
         ('Can I get a no-fault divorce in South Dakota if my spouse objects?', 'An irreconcilable differences divorce needs both spouses to agree or the other spouse not to respond; otherwise a fault ground is needed.'),
         ('How is child support calculated in South Dakota?', 'With an income shares model based on both parents\' net incomes.'),
         TAXQ('South Dakota')]),

us('north-dakota', 'North Dakota', cite='N.D.C.C. 14-05-24 (property, Ruff-Fischer guidelines), 14-05-24.1 (spousal support), N.D. Admin. Code ch. 75-02-04.1 (child support), 14-05-17 (residency)',
   lede='North Dakota includes all property in the marital estate, divides it equitably using the Ruff-Fischer guidelines, and prefers rehabilitative spousal support. Here is how North Dakota handles the money, in plain language.',
   short='North Dakota puts <strong>all property, separate or joint</strong>, into the marital estate and divides it equitably using the <strong>Ruff-Fischer guidelines</strong>, starting from equal. Spousal support is usually <strong>rehabilitative</strong>. Child support is a schedule based on the <strong>paying parent\'s net income</strong>. There is <strong>no waiting period</strong>.',
   prop=['Under N.D.C.C. 14-05-24, the court makes an equitable distribution of all property and debts. It starts from an equal division and applies the Ruff-Fischer guidelines: age, earning ability, the length of the marriage, conduct, station in life, health, the property each holds and its income-producing capacity, and how it was acquired.'],
   separate='All property, including what one spouse brought in, inherited or received as a gift, is part of the marital estate. How and when it was acquired is a Ruff-Fischer factor, so the court may still award it to its owner.',
   alimony=['North Dakota courts may award temporary, <strong>rehabilitative</strong> (preferred) or permanent spousal support, using the Ruff-Fischer factors; there is no formula. Support other than rehabilitative support ends on the recipient\'s remarriage or on cohabitation for a year or more.'],
   child='North Dakota uses an obligor model: support comes from a schedule based on the <strong>paying parent\'s net income</strong> and the number of children, with adjustments for extended parenting time.',
   timing='The filing spouse must have lived in North Dakota for six months before the decree is entered (you can file sooner). There is no separation requirement or waiting period. Couples with modest assets can use a summary divorce process.',
   glance=[('Property division', 'All property, equitable; Ruff-Fischer guidelines (14-05-24)'), ('Separate property', 'Included; source is a factor'),
           ('Spousal support', 'Rehabilitative preferred (14-05-24.1)'), ('Child support', 'Schedule based on paying parent\'s net income'), ('Residency', '6 months before decree; no wait')],
   faqs=[('Is premarital property divided in North Dakota?', 'All property is part of the marital estate, but how and when it was acquired is one of the Ruff-Fischer factors, so the court may award it to its owner.'),
         ('What are the Ruff-Fischer guidelines?', 'Factors from North Dakota case law used to divide property and set support, including age, earning ability, length of marriage, conduct, health and the property each spouse holds.'),
         ('Is alimony permanent in North Dakota?', 'Usually not. Courts prefer rehabilitative support; permanent support is possible but less common.'),
         ('How is child support calculated in North Dakota?', 'From a schedule based on the paying parent\'s net income and the number of children.'),
         TAXQ('North Dakota')]),

us('alaska', 'Alaska', cite='AS 25.24.160 (property and spousal support), AS 34.77 (opt-in community property), Alaska Civil Rule 90.3 (child support), AS 25.24.090 (residency)',
   lede='Alaska divides marital property equitably, lets couples opt into community property by agreement, and sets child support as a percentage of the paying parent\'s income. Here is how Alaska handles the money, in plain language.',
   short='Alaska is an <strong>equitable distribution</strong> state that divides marital property without regard to fault, and couples can <strong>opt into community property</strong> by written agreement. Spousal support is usually <strong>rehabilitative or reorientation</strong> support. Child support is a <strong>percentage of the paying parent\'s adjusted income</strong>: 20% for one child, 27% for two, 33% for three.',
   prop=['Under AS 25.24.160, the court divides marital property equitably, without regard to fault, using a three-step approach: decide what is marital, value it, then divide it fairly. Retirement benefits earned during the marriage are divisible.'],
   separate='Property owned before the marriage, gifts and inheritances are generally separate, but they can become marital if the spouses treated them as joint (for example by mixing them in or using them as the family home). Spouses who signed a community property agreement under AS 34.77 divide that property as the court finds just.',
   alimony=['Alaska spousal support has no formula. Courts favor <strong>rehabilitative</strong> support (for training) and <strong>reorientation</strong> support (short-term help adjusting after the divorce); permanent support is rare. A material change in circumstances can justify modification.'],
   child='Alaska Civil Rule 90.3 sets child support as a <strong>percentage of the paying parent\'s adjusted annual income</strong>: <strong>20%</strong> for one child, <strong>27%</strong> for two, <strong>33%</strong> for three, plus 3% for each additional child, with a shared custody formula when each parent has at least 30% of overnights.',
   timing='The filing spouse must be an Alaska resident when filing (physically present with intent to stay). There is about a 30-day period after filing before a decree, and a standing order on filing bars moving assets or children out of the state. Permanent Fund Dividends for the children are often addressed in the parenting plan.',
   glance=[('Property division', 'Equitable, no fault (AS 25.24.160)'), ('Community property', 'Optional by written agreement (AS 34.77)'),
           ('Spousal support', 'Rehabilitative and reorientation favored'), ('Child support', '20% / 27% / 33%, +3% each additional child (Rule 90.3)'), ('Residency', 'Resident at filing')],
   faqs=[('Is Alaska a community property state?', 'Not by default. Alaska divides marital property equitably, but couples can opt into community property by signing a written agreement.'),
         ('How much is child support in Alaska?', 'Under Civil Rule 90.3, a percentage of the paying parent\'s adjusted annual income: 20% for one child, 27% for two, 33% for three, plus 3% for each additional child.'),
         ('Is alimony permanent in Alaska?', 'Rarely. Courts favor rehabilitative and short-term reorientation support.'),
         ('Do I need to live in Alaska for a while before divorcing?', 'No minimum period: the filing spouse must be an Alaska resident, physically present with the intent to stay, when filing.'),
         TAXQ('Alaska')]),

us('vermont', 'Vermont', cite='15 V.S.A. 751 (property), 752 (maintenance), 15 V.S.A. 653 to 657 (child support guidelines), 592 and 593 (residency), 551(7) (six months apart), 554 (nisi period)',
   lede='Vermont can divide all property either spouse owns, starting from an equal split, and every divorce has a 90-day nisi period before it becomes final. Here is how Vermont handles the money, in plain language.',
   short='Vermont divides <strong>all property of either spouse</strong>, however acquired, starting from an <strong>equal split</strong> and adjusting for the statutory factors. Maintenance is usually <strong>rehabilitative</strong>, and does not end automatically on remarriage. No-fault divorce needs <strong>six months apart</strong>, and every divorce has a <strong>90-day nisi period</strong>.',
   prop=['Under 15 V.S.A. 751, the court can divide all property owned by either or both spouses, however and whenever acquired. It starts from an equal division and adjusts it using factors such as the length of the marriage, income, contributions including homemaking, and economic misconduct such as wasting assets.'],
   separate='Premarital property, gifts and inheritances are not excluded automatically, but where property came from is one of the factors, and courts often return such property to its owner when the other spouse did not contribute to it.',
   alimony=['Vermont maintenance requires that the requesting spouse lacks enough income or property to provide for reasonable needs and cannot support themselves at the marital standard of living, or is caring for a child. Courts weigh the factors in 15 V.S.A. 752 and may refer to the state\'s advisory maintenance guidelines. Rehabilitative maintenance is most common. Maintenance does not end automatically on remarriage or cohabitation; the paying spouse must ask for a review.'],
   child='Vermont uses an <strong>income shares</strong> model under its child support guidelines, combining both parents\' incomes and sharing the schedule amount in proportion to income.',
   timing='One spouse must have lived in Vermont for six months before filing and one year before the final hearing. A no-fault divorce requires six consecutive months living separate and apart (possible under one roof with separate lives). After the final order, a 90-day nisi period runs before the divorce is final; it can be waived in agreed cases.',
   glance=[('Property division', 'All property; starts from equal (15 V.S.A. 751)'), ('Separate property', 'Not automatically excluded; source is a factor'),
           ('Maintenance', 'Rehabilitative most common; no automatic end on remarriage (752)'), ('Child support', 'Income shares'), ('Timing', '6 months apart; 90-day nisi period')],
   faqs=[('Is property split 50/50 in Vermont?', 'The court starts from an equal division of all property, then adjusts it using the statutory factors.'),
         ('Does maintenance end when my ex remarries in Vermont?', 'Not automatically. The paying spouse must ask the court to review it and show a significant change in circumstances.'),
         ('What is the nisi period in Vermont?', 'A 90-day period after the final order before the divorce becomes final. It can be waived in agreed cases but not contested ones.'),
         ('How is child support calculated in Vermont?', 'With an income shares model based on both parents\' incomes.'),
         TAXQ('Vermont')]),

us('wyoming', 'Wyoming', cite='W.S. 20-2-114 (property and alimony), 20-2-116 (modification), W.S. 20-2-301 et seq. (child support), 20-2-107 (60-day residency)',
   lede='Wyoming divides all property in a just and equitable way, can weigh the respective merits of the spouses, and has one of the shortest residency requirements in the country. Here is how Wyoming handles the money, in plain language.',
   short='Wyoming makes a <strong>just and equitable</strong> division of <strong>all property</strong>, marital and separate, and growth on separate property during the marriage is generally marital. Courts consider the <strong>respective merits</strong> of the parties, so conduct can matter. Alimony is <strong>reasonable alimony</strong> with no formula. Residency is <strong>60 days</strong>, and there is a <strong>20-day</strong> wait.',
   prop=['Under W.S. 20-2-114, the court makes a just and equitable division of the parties\' property, considering the respective merits of the parties, the condition each will be left in, who acquired the property, and the burdens on it. Wyoming can reach both marital and separate property.'],
   separate='Property brought into the marriage, gifts and inheritances are not automatically excluded, but how property was acquired is a factor. Appreciation of separate property during the marriage is generally treated as marital.',
   alimony=['Wyoming courts may award reasonable alimony, lump sum or periodic, rehabilitative or indefinite, with wide discretion and no formula. Statutory factors include the paying spouse\'s ability to pay, the other\'s need, the condition each is left in and their respective merits; case law adds the length of the marriage, age, health, earning capacity and contributions. It generally ends on remarriage or death unless the decree says otherwise.'],
   child='Wyoming uses an <strong>income shares</strong> model, combining both parents\' net incomes and sharing the presumptive amount in proportion to income, with a shared custody adjustment. Since July 2025, Wyoming presumes shared custody, with exceptions.',
   timing='One spouse must have lived in Wyoming for 60 days before filing, or you married in Wyoming and one spouse has lived there since. The decree cannot be entered until 20 days after filing and service. There is no separation requirement and no waiting period before remarriage.',
   glance=[('Property division', 'Just and equitable division of all property (W.S. 20-2-114)'), ('Separate property growth', 'Generally marital'),
           ('Alimony', 'Reasonable alimony; no formula; merits can count'), ('Child support', 'Income shares'), ('Residency and wait', '60 days; 20 days')],
   faqs=[('How is property divided in a Wyoming divorce?', 'In a just and equitable way. The court can reach all property, marital and separate, and considers the respective merits of the parties.'),
         ('Does fault matter in a Wyoming divorce?', 'Fault is not needed for the divorce, but the court can consider the respective merits of the parties when dividing property and setting alimony.'),
         ('How long do I need to live in Wyoming to divorce?', '60 days before filing, or since the marriage if you married in Wyoming.'),
         ('How is child support calculated in Wyoming?', 'With an income shares model based on both parents\' net incomes.'),
         TAXQ('Wyoming')]),

us('district-of-columbia', 'Washington, D.C.', cite='D.C. Code 16-910 (property), 16-913 (alimony), 16-916.01 (child support guideline), 16-902 (residency), 16-904 (grounds after Jan 26, 2024)',
   lede='Washington, D.C. returns each spouse\'s separate property, divides the rest in a way that is equitable, just and reasonable, and since 2024 lets either spouse divorce simply because they no longer wish to be married. Here is how D.C. handles the money, in plain language.',
   short='D.C. first returns each spouse\'s <strong>sole and separate property</strong> (premarital, gifts, inheritances and their growth), then divides the rest in a way that is <strong>equitable, just and reasonable</strong>, with <strong>no 50/50 presumption</strong>. Alimony can be <strong>indefinite or term-limited</strong>. Child support uses <strong>income shares</strong>. Since <strong>January 2024</strong> no separation period is needed.',
   prop=['Under D.C. Code 16-910, the court first assigns each spouse\'s sole and separate property, then divides all other property and debt in a way that is equitable, just and reasonable. There is no presumption of an equal split. Factors include the length of the marriage, each spouse\'s needs and earning capacity, homemaker contributions, and, since 2024, any history of abuse.'],
   separate='Sole and separate property includes what you owned before the marriage and anything received during it by gift, bequest or inheritance, <strong>plus any increase in its value</strong>.',
   alimony=['D.C. alimony can be <strong>indefinite or for a set term</strong>, and can be backdated to when it was requested. Under D.C. Code 16-913, the court weighs the ability to become self-supporting, time for training, the standard of living, the length of the marriage, the circumstances of the separation (including abuse), age, health, and each party\'s needs and resources.'],
   child='D.C. uses an <strong>income shares</strong> guideline, combining both parents\' incomes and sharing the schedule amount in proportion to income, with adjustments for shared parenting.',
   timing='One spouse must have lived in D.C. for six months before filing. Since January 26, 2024 (Elaine\'s Law), a spouse can file simply by stating they no longer wish to remain married, without the old six-month or one-year separation.',
   glance=[('Property division', 'Separate returned; rest equitable, just and reasonable (16-910)'), ('Separate property', 'Premarital, gifts, inheritances and their growth'),
           ('Alimony', 'Indefinite or term-limited (16-913)'), ('Child support', 'Income shares guideline'), ('Grounds', 'No separation needed since Jan 2024')],
   faqs=[('Is property split 50/50 in a D.C. divorce?', 'No. After each spouse\'s separate property is returned, the rest is divided in a way that is equitable, just and reasonable, with no presumption of an equal split.'),
         ('Is growth on separate property divided in D.C.?', 'No. Sole and separate property includes any increase in its value.'),
         ('Do I need to be separated to divorce in D.C.?', 'Not since January 26, 2024. A spouse can file by stating they no longer wish to remain married.'),
         ('How is child support calculated in D.C.?', 'With an income shares guideline based on both parents\' incomes.'),
         TAXQ('Washington, D.C.')]),
]
for g in GUIDES:
    g['about'][0] = g['name'] + ' divorce'
